fn main() {
    let dir = std::env::var("CARGO_MANIFEST_DIR").unwrap();
    println!("cargo:rustc-link-arg=-T{dir}/linker.ld");
    println!("cargo:rerun-if-changed=linker.ld");
    for asm in ["src/boot/entry.S", "src/trap/trap.S", "src/task/switch.S"] {
        println!("cargo:rerun-if-changed={asm}");
    }
}

kernel/linker.ld.text:
/* Memory layout of the Micro-OS on QEMU `virt` (RAM starts at 0x8000_0000).
 *
 *   0x8000_0000  OpenSBI firmware (M-mode, PMP-protected from the kernel)
 *   0x8020_0000  kernel image: .text .rodata .data, boot stack, .bss
 *   __heap_start kernel heap (HEAP_SIZE bytes, see src/memory/mod.rs)
 */
OUTPUT_ARCH(riscv)
ENTRY(_start)
BASE_ADDRESS = 0x80200000;

SECTIONS
{
    . = BASE_ADDRESS;
    __kernel_start = .;

    .text : {
        *(.text.entry)          /* _start must be first: OpenSBI jumps here */
        *(.text .text.*)
    }

    . = ALIGN(4K);
    .rodata : {
        *(.rodata .rodata.*)
        *(.srodata .srodata.*)
    }

    . = ALIGN(4K);
    .data : {
        *(.data .data.*)
        *(.sdata .sdata.*)
    }

    . = ALIGN(4K);
    .stack (NOLOAD) : {
        __boot_stack_bottom = .;
        . += 64K;
        __boot_stack_top = .;
    }

    .bss (NOLOAD) : {
        __bss_start = .;
        *(.bss .bss.*)
        *(.sbss .sbss.*)
        . = ALIGN(8);
        __bss_end = .;
    }

    . = ALIGN(4K);
    __kernel_end = .;
    __heap_start = .;

    /DISCARD/ : {
        *(.eh_frame)
        *(.eh_frame_hdr)
    }
}

kernel/src/arch.rs.text:
//! RISC-V supervisor-mode CSR access. Every inline-asm block in the kernel
//! outside the three `.S` files lives here, behind small safe functions.
//!
//! The interrupt on/off helpers deliberately omit `nomem` so they also act
//! as compiler barriers: memory accesses cannot be moved across them.

use core::arch::asm;

pub const SSTATUS_SIE: usize = 1 << 1;
pub const SIE_STIE: usize = 1 << 5;
pub const SCAUSE_INTERRUPT: usize = 1 << 63;
pub const IRQ_S_TIMER: usize = 5;

/// Value of the `time` CSR (10 MHz on QEMU virt).
#[inline]
pub fn read_time() -> u64 {
    let t: u64;
    // SAFETY: reading `time` has no side effects.
    unsafe { asm!("rdtime {}", out(reg) t, options(nomem, nostack)) };
    t
}

#[inline]
pub fn intr_on() {
    // SAFETY: setting sstatus.SIE only allows pending, enabled interrupts in.
    unsafe { asm!("csrsi sstatus, 2", options(nostack)) };
}

#[inline]
pub fn intr_off() {
    // SAFETY: clearing sstatus.SIE only masks interrupts.
    unsafe { asm!("csrci sstatus, 2", options(nostack)) };
}

#[inline]
pub fn intr_enabled() -> bool {
    read_sstatus() & SSTATUS_SIE != 0
}

#[inline]
pub fn read_sstatus() -> usize {
    let v: usize;
    // SAFETY: plain CSR read.
    unsafe { asm!("csrr {}, sstatus", out(reg) v, options(nomem, nostack)) };
    v
}

pub fn enable_timer_interrupt() {
    // SAFETY: unmasks the supervisor timer interrupt source only.
    unsafe { asm!("csrs sie, {}", in(reg) SIE_STIE, options(nostack)) };
}

/// Install the trap vector (direct mode: all traps enter at `addr`).
///
/// # Safety
/// `addr` must be the 4-byte-aligned address of a correct trap entry routine.
pub unsafe fn write_stvec(addr: usize) {
    asm!("csrw stvec, {}", in(reg) addr, options(nostack));
}

/// Mark "currently in the kernel" for trap.S (see the sscratch protocol there).
pub fn clear_sscratch() {
    // SAFETY: sscratch is only read by trap.S; zero means "trap from S-mode",
    // which is true whenever this runs.
    unsafe { asm!("csrw sscratch, zero", options(nomem, nostack)) };
}

pub fn read_scause() -> usize {
    let v: usize;
    // SAFETY: plain CSR read.
    unsafe { asm!("csrr {}, scause", out(reg) v, options(nomem, nostack)) };
    v
}

pub fn read_stval() -> usize {
    let v: usize;
    // SAFETY: plain CSR read.
    unsafe { asm!("csrr {}, stval", out(reg) v, options(nomem, nostack)) };
    v
}

/// Current frame pointer (s0), for backtraces.
#[inline(always)]
pub fn read_fp() -> usize {
    let v: usize;
    // SAFETY: copies a register.
    unsafe { asm!("mv {}, s0", out(reg) v, options(nomem, nostack)) };
    v
}

/// Wait for an interrupt. Returns when one is pending *and enabled in `sie`*,
/// even if sstatus.SIE is clear, which is what the idle loop relies on.
#[inline]
pub fn wfi() {
    // SAFETY: wfi is a hint; the worst case is that it returns immediately.
    unsafe { asm!("wfi", options(nomem, nostack)) };
}

kernel/src/main.rs.text:
//! Micro-OS: an educational RISC-V kernel in Rust (CA-6).
//!
//! Boot path: OpenSBI (M-mode) → `_start` (boot/entry.S) → `kmain` (S-mode).
//! `kmain` initialises each layer in order, then runs the scenarios selected
//! on the kernel command line and exits QEMU with the number of failed checks.

#![no_std]
#![no_main]

extern crate alloc;

#[macro_use]
mod kernel;

mod arch;
mod boot;
mod drivers;
mod memory;
mod programs;
mod scenarios;
mod scheduler;
mod shell;
mod sync;
mod sys;
mod task;
mod timer;
mod trap;
mod user;

use drivers::{qemu_exit, sbi};
use kernel::console::{self, Level};

#[no_mangle]
pub extern "C" fn kmain(hartid: usize, dtb: usize) -> ! {
    println!();
    kinfo!("Micro-OS v{} booting on hart {} (riscv64, S-mode)", env!("CARGO_PKG_VERSION"), hartid);
    ktrace!("BOOT", "stage=entry hart={} dtb={:#x}", hartid, dtb);
    let (major, minor) = sbi::spec_version();
    kinfo!("firmware: {} implementing SBI v{}.{}", sbi::impl_name(), major, minor);

    let args = boot::boot_args(dtb);
    if let Some(level) = args.get("log").and_then(Level::parse) {
        console::set_level(level);
    }
    console::set_trace(args.flag("trace", true));
    kinfo!("command line: '{}'", args.raw());
    ktrace!("BOOT", "stage=args fw={} sbi={}.{}", sbi::impl_name(), major, minor);

    trap::init();
    kinfo!("trap vector installed");
    ktrace!("BOOT", "stage=trap");

    let (heap_start, heap_size) = memory::init();
    let (kstart, kend) = memory::kernel_image();
    kinfo!("kernel image {:#x}..{:#x} ({} KiB)", kstart, kend, (kend - kstart) / 1024);
    kinfo!("heap {:#x}..{:#x} ({} KiB, first-fit free list)", heap_start, heap_start + heap_size, heap_size / 1024);
    ktrace!("BOOT", "stage=heap start={:#x} size={} kimg={:#x}-{:#x}", heap_start, heap_size, kstart, kend);

    let tick_us = args.get_u64("tick_us").unwrap_or(1000);
    timer::init(tick_us);
    arch::intr_on();
    kinfo!("timer running: one tick every {} us", tick_us);
    ktrace!("BOOT", "stage=timer tick_us={}", tick_us);

    let test = args.get("test").unwrap_or("all");
    let failed = scenarios::run(test, &args);

    let h = memory::stats();
    kinfo!(
        "heap at shutdown: in_use={} B peak={} B allocs={} frees={} failed={} rejected_frees={} free_blocks={}",
        h.bytes_in_use, h.peak_bytes, h.allocs, h.frees, h.failed, h.rejected_frees, h.free_blocks
    );
    ktrace!(
        "HEAP",
        "in_use={} peak={} allocs={} frees={} failed={} rejected={} free_blocks={} largest={}",
        h.bytes_in_use, h.peak_bytes, h.allocs, h.frees, h.failed, h.rejected_frees, h.free_blocks, h.largest_free
    );
    kinfo!("ticks={} - shutting down with exit code {}", timer::ticks(), failed);
    ktrace!("SHUTDOWN", "failed={}", failed);
    qemu_exit::exit(failed)
}

kernel/src/sys.rs.text:
//! Layer 9 — system interface for programs.
//!
//! Programs in `src/programs/` should use only this module (plus `println!`
//! and `alloc` collections). It is the boundary between "application" code
//! and kernel internals, like a system-call table. These programs run in
//! S-mode as kernel tasks, so the boundary is by convention only. Programs
//! that need a hardware-enforced boundary run in U-mode instead and reach
//! the kernel through real `ecall` system calls: see `crate::user`.

use crate::{memory, scheduler, timer};

/// Task id of the calling program.
pub fn getpid() -> usize {
    scheduler::current_tid().unwrap_or(0)
}

/// Milliseconds since boot.
pub fn uptime_ms() -> u64 {
    timer::now_us() / 1000
}

/// Timer ticks this program has been charged for (its CPU time).
pub fn cpu_ticks() -> u64 {
    scheduler::current_cpu_ticks()
}

/// Length of one timer tick in microseconds.
pub fn tick_us() -> u64 {
    timer::tick_us()
}

/// Sleep (BLOCKED, using no CPU) for at least `ms` milliseconds.
/// Returns `false` if the user pressed Ctrl-C, so callers can stop early.
pub fn sleep_ms(ms: u64) -> bool {
    let ticks = (ms * 1000).div_ceil(timer::tick_us()).max(1);
    scheduler::sleep_ticks(ticks);
    !interrupted()
}

/// Give the CPU to another ready task.
pub fn yield_now() {
    scheduler::yield_now();
}

/// Has the user asked this program to stop (Ctrl-C or `kill`)?
/// Long-running loops should check this regularly.
pub fn interrupted() -> bool {
    scheduler::cancel_requested()
}

/// Bytes currently allocated on the kernel heap (all tasks together).
pub fn heap_used() -> usize {
    memory::stats().bytes_in_use
}

kernel/src/programs/counter.rs.text:
//! Counts slowly. Between numbers the task is BLOCKED (sleeping), so it uses
//! almost no CPU: compare its CPU ticks in `ps` with `spin`'s.

use super::arg_u64;
use crate::sys;

pub fn main(args: &[&str]) -> i32 {
    let n = arg_u64(args, 0, 10);
    let ms = arg_u64(args, 1, 500);
    let pid = sys::getpid();
    for i in 1..=n {
        println!("[counter pid {}] {} / {}", pid, i, n);
        if !sys::sleep_ms(ms) {
            println!("[counter pid {}] interrupted", pid);
            return 130;
        }
    }
    println!("[counter pid {}] done, used {} CPU ticks", pid, sys::cpu_ticks());
    0
}

kernel/src/programs/fib.rs.text:
use super::arg_u64;

pub fn main(args: &[&str]) -> i32 {
    let n = arg_u64(args, 0, 40);
    if n > 186 {
        println!("fib: n must be <= 186 (larger values overflow u128)");
        return 1;
    }
    let (mut a, mut b) = (0u128, 1u128);
    for i in 0..=n {
        if i < 10 || i == n {
            println!("fib({}) = {}", i, a);
        } else if i == 10 {
            println!("...");
        }
        (a, b) = (b, a + b);
    }
    0
}

kernel/src/programs/hello.rs.text:
use crate::sys;

pub fn main(args: &[&str]) -> i32 {
    println!("Hello from a Rust program running on the Micro-OS!");
    println!("  my task id (pid) : {}", sys::getpid());
    println!("  uptime           : {} ms", sys::uptime_ms());
    if args.is_empty() {
        println!("  no arguments (try: run hello world 42)");
    }
    for (i, a) in args.iter().enumerate() {
        println!("  arg[{}]           : {}", i, a);
    }
    0
}

kernel/src/programs/memtest.rs.text:
//! Exercises the kernel heap (the free-list allocator) from a program.

use alloc::vec::Vec;

use super::arg_u64;
use crate::sys;

pub fn main(args: &[&str]) -> i32 {
    let kib = arg_u64(args, 0, 256) as usize;
    let before = sys::heap_used();
    let mut buf: Vec<u8> = Vec::new();
    if buf.try_reserve_exact(kib * 1024).is_err() {
        println!("memtest: could not allocate {} KiB (heap exhausted)", kib);
        return 1;
    }
    buf.resize(kib * 1024, 0);
    for (i, b) in buf.iter_mut().enumerate() {
        *b = (i % 251) as u8;
    }
    let ok = buf.iter().enumerate().all(|(i, &b)| b == (i % 251) as u8);
    let during = sys::heap_used();
    drop(buf);
    let after = sys::heap_used();
    println!("memtest: {} KiB written and verified: {}", kib, if ok { "OK" } else { "CORRUPTED" });
    println!("  heap in use: before={} B  during={} B  after={} B", before, during, after);
    if ok {
        0
    } else {
        2
    }
}

kernel/src/programs/mod.rs.text:
//! Programs you can start from the shell: `run <name> [args...]`.
//!
//! ## Adding your own program
//!
//! 1. Copy `template.rs` to e.g. `myprog.rs` and edit `main`.
//! 2. Add `mod myprog;` below and one line to `PROGRAMS`.
//! 3. `scripts/shell.sh`, then type `run myprog` (or just `myprog`).
//!
//! Each program runs as its own kernel task, scheduled alongside the shell
//! and any other program, so `ps`, `sched` and `top` show it working.
//! Use only `crate::sys::*`, `println!`/`print!`, and `alloc` types.

mod counter;
mod fib;
mod hello;
mod memtest;
mod pingpong;
mod primes;
mod spin;
mod template;
mod user;

pub struct Program {
    pub name: &'static str,
    pub usage: &'static str,
    pub about: &'static str,
    /// Receives the words after the program name; returns an exit code.
    pub main: fn(&[&str]) -> i32,
}

pub const PROGRAMS: &[Program] = &[
    Program { name: "hello", usage: "hello [args...]", about: "print a greeting, pid and arguments", main: hello::main },
    Program { name: "counter", usage: "counter [n=10] [ms=500]", about: "count with sleeps (BLOCKED between numbers)", main: counter::main },
    Program { name: "primes", usage: "primes [limit=200000]", about: "CPU-bound prime counting", main: primes::main },
    Program { name: "fib", usage: "fib [n=40]", about: "Fibonacci numbers with u128", main: fib::main },
    Program { name: "spin", usage: "spin [seconds=5] [yield]", about: "CPU hog (or polite with 'yield'): shows its CPU share", main: spin::main },
    Program { name: "memtest", usage: "memtest [kib=256]", about: "allocate, fill, verify and free heap memory", main: memtest::main },
    Program { name: "pingpong", usage: "pingpong [rounds=20] [ms=80]", about: "two tasks hand two semaphores back and forth (real wake-ups)", main: pingpong::main },
    Program { name: "user", usage: "user [hello|priv|badptr|unknown|spin] [arg]", about: "run a program in U-mode; it reaches the kernel only via ecall", main: user::main },
    Program { name: "template", usage: "template", about: "starting point for your own program", main: template::main },
];

pub fn find(name: &str) -> Option<&'static Program> {
    PROGRAMS.iter().find(|p| p.name == name)
}

/// Parse argument `i` as a number, or use `default` if it is missing/invalid.
pub fn arg_u64(args: &[&str], i: usize, default: u64) -> u64 {
    args.get(i).and_then(|a| a.parse().ok()).unwrap_or(default)
}

kernel/src/programs/pingpong.rs.text:
//! pingpong: two tasks take turns through two semaphores.
//!
//! `ping` (this program's task) signals `to_pong` and blocks on `to_ping`;
//! a second task, `pong`, does the reverse. Every signal wakes the other task,
//! so the kernel traces a `WAKE tid=X by=Y` for each hand-off: a real
//! task-to-task wake-up (the kernel has no message-passing IPC; this is how
//! its tasks hand work to each other).
//!
//! Usage: pingpong [rounds=20] [ms=80]   (ms: pause between rounds)

use alloc::sync::Arc;
use core::sync::atomic::{AtomicBool, Ordering};

use super::arg_u64;
use crate::scheduler::{self, SpawnOpts};
use crate::sync::Semaphore;
use crate::sys;

struct Table {
    to_ping: Semaphore,
    to_pong: Semaphore,
    stop: AtomicBool,
}

pub fn main(args: &[&str]) -> i32 {
    let rounds = arg_u64(args, 0, 20).clamp(1, 10_000);
    let pause = arg_u64(args, 1, 80);
    let t = Arc::new(Table {
        to_ping: Semaphore::new("to_ping", 0),
        to_pong: Semaphore::new("to_pong", 0),
        stop: AtomicBool::new(false),
    });

    let peer = Arc::clone(&t);
    let spawned = scheduler::spawn("pong", SpawnOpts { prio: 4, ..SpawnOpts::default() }, move || {
        for i in 1..=rounds {
            peer.to_pong.wait();
            if peer.stop.load(Ordering::Acquire) {
                return;
            }
            println!("  pong (pid {}) <- {}", sys::getpid(), i);
            peer.to_ping.signal();
        }
    });
    let pong = match spawned {
        Ok(tid) => tid,
        Err(e) => {
            println!("pingpong: could not start pong: {:?}", e);
            return 1;
        }
    };
    println!("pingpong: ping is pid {}, pong is pid {}, {} rounds", sys::getpid(), pong, rounds);

    for i in 1..=rounds {
        println!("ping (pid {}) -> {}", sys::getpid(), i);
        t.to_pong.signal(); // wakes pong
        t.to_ping.wait(); // blocks until pong wakes us
        if !sys::sleep_ms(pause) {
            // Ctrl-C: release pong so it can finish too.
            t.stop.store(true, Ordering::Release);
            t.to_pong.signal();
            return 130;
        }
    }
    0
}

kernel/src/programs/primes.rs.text:
//! CPU-bound: counts primes by trial division. Never sleeps, so the timer
//! interrupt is what forces it to share the CPU.

use super::arg_u64;
use crate::sys;

fn is_prime(n: u64) -> bool {
    if n < 2 {
        return false;
    }
    let mut d = 2;
    while d * d <= n {
        if n % d == 0 {
            return false;
        }
        d += 1;
    }
    true
}

pub fn main(args: &[&str]) -> i32 {
    let limit = arg_u64(args, 0, 200_000);
    let start = sys::uptime_ms();
    let mut count = 0u64;
    let mut largest = 0;
    for n in 0..=limit {
        if n % 1000 == 0 && sys::interrupted() {
            println!("primes: interrupted at {} ({} primes so far)", n, count);
            return 130;
        }
        if is_prime(n) {
            count += 1;
            largest = n;
        }
    }
    println!(
        "primes: {} primes <= {} (largest {}) in {} ms wall time, {} CPU ticks",
        count, limit, largest, sys::uptime_ms() - start, sys::cpu_ticks()
    );
    0
}

kernel/src/programs/spin.rs.text:
//! A CPU hog. Run two in the background (`spin 10 &` twice), then use `ps`
//! or `top`: the scheduler splits the CPU between them, and each reports
//! what share of the wall-clock time it actually received.
//!
//! `spin 5 yield` is the polite version: it calls `sys::yield_now()` after
//! every chunk of work, handing the CPU to anyone else who is ready.

use super::arg_u64;
use crate::sys;

pub fn main(args: &[&str]) -> i32 {
    let seconds = arg_u64(args, 0, 5);
    let polite = args.get(1) == Some(&"yield");
    let start = sys::uptime_ms();
    let mut loops = 0u64;
    while sys::uptime_ms() - start < seconds * 1000 {
        if sys::interrupted() {
            break;
        }
        for i in 0..1000u32 {
            core::hint::black_box(i);
        }
        loops += 1;
        if polite {
            sys::yield_now();
        }
    }
    let wall_ms = (sys::uptime_ms() - start).max(1);
    let cpu_ms = sys::cpu_ticks() * sys::tick_us() / 1000;
    println!(
        "[spin pid {}] {} ms wall, ~{} ms CPU ({}% share), {} loops",
        sys::getpid(), wall_ms, cpu_ms, cpu_ms * 100 / wall_ms, loops
    );
    0
}

kernel/src/programs/template.rs.text:
//! Copy this file to start your own program (see programs/mod.rs).
//!
//! What you can use:
//!   println!(...) / print!(...)      write to the console
//!   sys::getpid()                    your task id
//!   sys::sleep_ms(ms) -> bool        sleep; false if Ctrl-C was pressed
//!   sys::yield_now()                 let another task run
//!   sys::interrupted() -> bool       check for Ctrl-C in long loops
//!   sys::uptime_ms(), sys::cpu_ticks(), sys::heap_used()
//!   super::arg_u64(args, i, default) read a numeric argument
//!   alloc::vec::Vec, alloc::string::String, ...  heap collections
//!
//! Return 0 for success, anything else for an error.

use super::arg_u64;
use crate::sys;

pub fn main(args: &[&str]) -> i32 {
    let times = arg_u64(args, 0, 3);
    for i in 1..=times {
        println!("template (pid {}): step {} of {}", sys::getpid(), i, times);
        if !sys::sleep_ms(200) {
            return 130;
        }
    }
    0
}

kernel/src/programs/user.rs.text:
//! `user PROG [arg]`: start a program in U-mode (unprivileged) and wait for it.
//!
//! The U-mode programs live in `crate::user`; they talk to the kernel only
//! through `ecall` system calls. This launcher is an ordinary kernel task
//! that starts one as a separate task and reports how it ended.

use crate::{scheduler, sys, user};

pub fn main(args: &[&str]) -> i32 {
    let name = args.first().copied().unwrap_or("hello");
    let Some(prog) = user::program(name) else {
        println!("user: no user program '{}'", name);
        println!("  hello [n]   well-behaved: write, getpid, uptime_ms, sleep_ms, yield, exit");
        println!("  priv        runs a privileged instruction: the kernel kills it");
        println!("  badptr      passes a bad pointer to write: refused with -EFAULT");
        println!("  unknown     calls a system call that does not exist: -ENOSYS");
        println!("  spin [m]    m million loop steps in U-mode (preempted by the timer)");
        return 2;
    };
    let default_arg = match name {
        "hello" => 3,
        "spin" => 20,
        _ => 0,
    };
    let arg = super::arg_u64(args, 1, default_arg) as usize;
    let calls_before = user::SYSCALLS.load(core::sync::atomic::Ordering::Relaxed);
    // A static task name per program, so ps, the journal and the desktop can tell runs apart.
    let task_name = match name {
        "hello" => "user-hello",
        "priv" => "user-priv",
        "badptr" => "user-badptr",
        "unknown" => "user-unknown",
        "spin" => "user-spin",
        _ => "user",
    };
    let tid = match user::spawn(task_name, prog, arg) {
        Ok(t) => t,
        Err(e) => {
            println!("user: could not start: {:?}", e);
            return 1;
        }
    };
    println!("[started user program '{}' as pid {} in U-mode]", name, tid);
    while scheduler::is_alive(tid) {
        if !sys::sleep_ms(20) {
            scheduler::request_cancel(tid);
        }
    }
    let calls = user::SYSCALLS.load(core::sync::atomic::Ordering::Relaxed) - calls_before;
    match user::exit_code(tid) {
        Some(code) => {
            println!("[user pid {} exited with code {} after {} system calls]", tid, code, calls);
            code as i32
        }
        None => {
            println!("[user pid {} ended without an exit code]", tid);
            1
        }
    }
}

kernel/src/user/mod.rs.text:
//! Layer 9 extension — user mode and real system calls.
//!
//! A user program runs in RISC-V **U-mode** (the unprivileged level) on its
//! own user stack. The only way it can ask the kernel for anything is the
//! `ecall` instruction, which traps into S-mode:
//!
//! ```text
//!  U-mode program          trap.S (S-mode)            this module
//!  a7 = number, a0.. args
//!  ecall  ───────────────▶ switch to kernel stack,
//!                          save TrapFrame       ────▶ syscall(): check args,
//!                                                     do the work, a0 = result
//!  continues after ecall ◀ restore, sret to U-mode ◀──
//! ```
//!
//! Privileged instructions (CSR access, `sret`, `wfi`) fault in U-mode; the
//! kernel then kills only that program (`kill_current`) and keeps running.
//!
//! Limits, stated honestly: paging is off, so this is *privilege* separation
//! (instructions), not memory isolation. Pointers passed to `write` are
//! range-checked against RAM, but a user program could still read or write
//! kernel memory directly. Memory isolation needs page tables (future work).
//!
//! System call numbers follow the Linux RISC-V ABI where one exists.

use core::arch::asm;
use core::cell::UnsafeCell;
use core::sync::atomic::{AtomicIsize, AtomicUsize, Ordering::Relaxed};

use crate::scheduler::{self, SpawnError, SpawnOpts};
use microos_core::sched::Tid;
use crate::timer;
use crate::trap::TrapFrame;

pub const SYS_WRITE: usize = 64;
pub const SYS_EXIT: usize = 93;
pub const SYS_YIELD: usize = 124;
pub const SYS_GETPID: usize = 172;
/// Not in Linux (which has nanosleep with a struct): sleep for a0 milliseconds.
pub const SYS_SLEEP_MS: usize = 1000;
/// Not in Linux: milliseconds since boot.
pub const SYS_UPTIME_MS: usize = 1001;

pub const EFAULT: isize = -14;
pub const EINVAL: isize = -22;
pub const ENOSYS: isize = -38;
/// Exit code recorded for a program the kernel killed.
pub const KILLED: isize = -9;
/// Exit code for a program stopped with Ctrl-C / `kill` during a system call.
pub const INTERRUPTED: isize = -130;

const MAX_WRITE: usize = 1024;
/// Usable RAM on QEMU virt (128 MiB) above OpenSBI's 2 MiB.
const RAM: core::ops::Range<usize> = 0x8020_0000..0x8800_0000;

fn name_of(nr: usize) -> &'static str {
    match nr {
        SYS_WRITE => "write",
        SYS_EXIT => "exit",
        SYS_YIELD => "yield",
        SYS_GETPID => "getpid",
        SYS_SLEEP_MS => "sleep_ms",
        SYS_UPTIME_MS => "uptime_ms",
        _ => "unknown",
    }
}

// ---------------------------------------------------------------- statistics

pub static SYSCALLS: AtomicUsize = AtomicUsize::new(0);
pub static KILLS: AtomicUsize = AtomicUsize::new(0);
pub static BYTES_WRITTEN: AtomicUsize = AtomicUsize::new(0);

const EXIT_SLOTS: usize = 32;
static EXIT_TID: [AtomicUsize; EXIT_SLOTS] = [const { AtomicUsize::new(0) }; EXIT_SLOTS];
static EXIT_CODE: [AtomicIsize; EXIT_SLOTS] = [const { AtomicIsize::new(0) }; EXIT_SLOTS];
static EXIT_NEXT: AtomicUsize = AtomicUsize::new(0);

fn record_exit(tid: Tid, code: isize) {
    let i = EXIT_NEXT.fetch_add(1, Relaxed) % EXIT_SLOTS;
    EXIT_CODE[i].store(code, Relaxed);
    EXIT_TID[i].store(tid, Relaxed);
}

/// Exit code of a finished user task (most recent record), if known.
pub fn exit_code(tid: Tid) -> Option<isize> {
    let n = EXIT_NEXT.load(Relaxed);
    (0..n.min(EXIT_SLOTS))
        .map(|k| (n - 1 - k) % EXIT_SLOTS) // newest record first
        .find(|&i| EXIT_TID[i].load(Relaxed) == tid)
        .map(|i| EXIT_CODE[i].load(Relaxed))
}

// ---------------------------------------------------------------- user stacks

const STACK_SLOTS: usize = 8;
const USER_STACK: usize = 8 * 1024;

#[repr(C, align(16))]
struct Stacks(UnsafeCell<[[u8; USER_STACK]; STACK_SLOTS]>);
// SAFETY: each slot is used by at most one task, chosen through OWNER.
unsafe impl Sync for Stacks {}
static STACKS: Stacks = Stacks(UnsafeCell::new([[0; USER_STACK]; STACK_SLOTS]));
/// Tid owning each user stack slot (0 = free).
static OWNER: [AtomicUsize; STACK_SLOTS] = [const { AtomicUsize::new(0) }; STACK_SLOTS];

/// Reserve a user stack for `tid`; returns its initial (top) stack pointer.
fn claim_stack(tid: Tid) -> Option<usize> {
    let i = (0..STACK_SLOTS).find(|&i| OWNER[i].compare_exchange(0, tid, Relaxed, Relaxed).is_ok())?;
    let base = STACKS.0.get() as usize + i * USER_STACK;
    Some(base + USER_STACK)
}

fn release_stack(tid: Tid) {
    for o in &OWNER {
        let _ = o.compare_exchange(tid, 0, Relaxed, Relaxed);
    }
}

// ---------------------------------------------------------------- starting programs

/// A program that runs in U-mode. It receives one argument and must end with
/// the `exit` system call (it cannot return: there is nothing to return to).
pub type UserProgram = extern "C" fn(usize) -> !;

extern "C" {
    fn __enter_user(entry: usize, user_sp: usize, arg: usize) -> !;
}

#[derive(Debug, PartialEq)]
pub enum StartError {
    Spawn(SpawnError),
}

/// Start `prog` as a new task that drops to U-mode immediately.
pub fn spawn(name: &'static str, prog: UserProgram, arg: usize) -> Result<Tid, StartError> {
    scheduler::spawn(name, SpawnOpts::default(), move || {
        let tid = scheduler::current_tid().unwrap_or(0);
        let Some(sp) = claim_stack(tid) else {
            kwarn!("user: no free user stack for pid {} ({} in use)", tid, STACK_SLOTS);
            record_exit(tid, EINVAL);
            return;
        };
        ktrace!("USER_ENTER", "tid={} name={} entry={:#x} usp={:#x}", tid, name, prog as usize, sp);
        // SAFETY: `prog` is a U-mode-safe function (it only executes ordinary
        // instructions and ecall) and `sp` is the top of a user stack owned by
        // this task until it exits; __enter_user never returns.
        unsafe { __enter_user(prog as usize, sp, arg) }
    })
    .map_err(StartError::Spawn)
}

// ---------------------------------------------------------------- the trap side

/// Handle `ecall` from U-mode. Called by `trap_handler` with interrupts off;
/// `tf.sepc` already points past the ecall.
pub fn syscall(tf: &mut TrapFrame) {
    let (nr, a0, a1) = (tf.regs[17], tf.regs[10], tf.regs[11]);
    let tid = scheduler::current_tid().unwrap_or(0);
    SYSCALLS.fetch_add(1, Relaxed);
    if scheduler::cancel_requested() {
        exit_current(tid, INTERRUPTED);
    }
    let ret: isize = match nr {
        SYS_WRITE => sys_write(a0, a1),
        SYS_GETPID => tid as isize,
        SYS_YIELD => {
            scheduler::yield_now();
            0
        }
        SYS_SLEEP_MS => {
            let ticks = ((a0 as u64).saturating_mul(1000)).div_ceil(timer::tick_us()).max(1);
            scheduler::sleep_ticks(ticks);
            0
        }
        SYS_UPTIME_MS => (timer::now_us() / 1000) as isize,
        SYS_EXIT => exit_current(tid, a0 as isize),
        _ => ENOSYS,
    };
    ktrace!("SYSCALL", "tid={} nr={} name={} ret={}", tid, nr, name_of(nr), ret);
    tf.regs[10] = ret as usize;
}

fn sys_write(ptr: usize, len: usize) -> isize {
    if len > MAX_WRITE {
        return EINVAL;
    }
    let Some(end) = ptr.checked_add(len) else { return EFAULT };
    if ptr < RAM.start || end > RAM.end {
        return EFAULT;
    }
    // SAFETY: [ptr, ptr+len) lies inside RAM (checked above) and paging is
    // off, so the range is readable; the bytes are only copied to the console.
    let bytes = unsafe { core::slice::from_raw_parts(ptr as *const u8, len) };
    let Ok(text) = core::str::from_utf8(bytes) else { return EINVAL };
    print!("{}", text);
    BYTES_WRITTEN.fetch_add(len, Relaxed);
    len as isize
}

fn exit_current(tid: Tid, code: isize) -> ! {
    record_exit(tid, code);
    release_stack(tid);
    ktrace!("USER_EXIT", "tid={} code={}", tid, code);
    scheduler::exit_current()
}

/// A U-mode program caused an exception: report it and end only that task.
pub fn kill_current(what: &str, sepc: usize, stval: usize) -> ! {
    let tid = scheduler::current_tid().unwrap_or(0);
    KILLS.fetch_add(1, Relaxed);
    println!("[pid {} killed by the kernel: {} at {:#x} (stval {:#x})]", tid, what, sepc, stval);
    ktrace!("USER_KILL", "tid={} cause={} sepc={:#x}", tid, what, sepc);
    exit_current(tid, KILLED)
}

// ---------------------------------------------------------------- user programs
//
// Everything below runs in U-mode. It may only use ordinary instructions and
// `ecall`: no println!, no allocation, no locks (they touch CSRs).

#[inline(always)]
fn ecall(nr: usize, a0: usize, a1: usize) -> isize {
    let ret: isize;
    // SAFETY: ecall transfers control to the kernel's syscall handler, which
    // returns a value in a0 and preserves every other register.
    unsafe { asm!("ecall", inlateout("a0") a0 as isize => ret, in("a1") a1, in("a7") nr, options(nostack)) };
    ret
}

fn uwrite(s: &str) -> isize {
    ecall(SYS_WRITE, s.as_ptr() as usize, s.len())
}

fn uexit(code: isize) -> ! {
    ecall(SYS_EXIT, code as usize, 0);
    loop {} // never reached: exit does not return
}

/// Write `label` followed by a decimal number and a newline, without
/// formatting machinery (which would call kernel code).
fn uwrite_num(label: &str, v: u64) {
    let mut buf = [0u8; 24];
    let mut i = buf.len();
    let mut n = v;
    loop {
        i -= 1;
        buf[i] = b'0' + (n % 10) as u8;
        n /= 10;
        if n == 0 || i == 1 {
            break;
        }
    }
    uwrite(label);
    let digits = &buf[i..];
    ecall(SYS_WRITE, digits.as_ptr() as usize, digits.len());
    uwrite("\n");
}

/// `user hello [n]`: a well-behaved program using every system call.
pub extern "C" fn prog_hello(rounds: usize) -> ! {
    uwrite("hello from U-mode: this text reached the console through ecall -> write\n");
    uwrite_num("  my pid (getpid):        ", ecall(SYS_GETPID, 0, 0) as u64);
    uwrite_num("  uptime ms (uptime_ms):  ", ecall(SYS_UPTIME_MS, 0, 0) as u64);
    for i in 1..=rounds {
        ecall(SYS_SLEEP_MS, 100, 0);
        uwrite_num("  slept 100 ms, round ", i as u64);
    }
    ecall(SYS_YIELD, 0, 0);
    uexit(0)
}

/// `user priv`: tries a privileged instruction; the kernel kills it.
pub extern "C" fn prog_privileged(_: usize) -> ! {
    uwrite("user program: trying to read sstatus (a supervisor register)...\n");
    let v: usize;
    // SAFETY (for the kernel): executing this in U-mode raises an
    // illegal-instruction exception, which is the point of the demo.
    unsafe { asm!("csrr {}, sstatus", out(reg) v, options(nomem, nostack)) };
    uwrite_num("  should never print; read ", v as u64);
    uexit(1)
}

/// `user badptr`: passes a pointer outside RAM; write must refuse it.
pub extern "C" fn prog_bad_pointer(_: usize) -> ! {
    let r = ecall(SYS_WRITE, 0x10, 5);
    uwrite_num("user program: write(0x10, 5) was refused; minus the error code: ", (-r) as u64);
    uexit(r)
}

/// `user unknown`: calls a system call number the kernel does not have.
pub extern "C" fn prog_unknown(_: usize) -> ! {
    let r = ecall(4242, 0, 0);
    uwrite_num("user program: syscall 4242 returned minus ", (-r) as u64);
    uexit(r)
}

/// `user spin [millions]`: CPU-bound loop in U-mode, to show that the timer
/// interrupt preempts user code too.
pub extern "C" fn prog_spin(millions: usize) -> ! {
    let mut x: u64 = 0;
    let mut i = 0usize;
    while i < millions * 1_000_000 {
        x = core::hint::black_box(x.wrapping_mul(6364136223846793005).wrapping_add(1));
        i += 1;
    }
    uwrite_num("user spin finished, checksum low digits ", x % 1000);
    uexit(0)
}

pub fn program(name: &str) -> Option<UserProgram> {
    Some(match name {
        "hello" => prog_hello,
        "priv" => prog_privileged,
        "badptr" => prog_bad_pointer,
        "unknown" => prog_unknown,
        "spin" => prog_spin,
        _ => return None,
    })
}

