//! Interrupt and exception layer.

use crate::{arch, scheduler};

core::arch::global_asm!(include_str!("trap.S"));

extern "C" {
    fn __trap_entry();
}

/// Register state saved by `trap.S`; layout must match the assembly.
#[repr(C)]
pub struct TrapFrame {
    pub regs: [usize; 32],
    pub sstatus: usize,
    pub sepc: usize,
}

/// sstatus.SPP: the privilege level the trap came from (0 = U-mode).
const SSTATUS_SPP: usize = 1 << 8;
/// scause exception code for `ecall` executed in U-mode.
const EXC_ECALL_FROM_U: usize = 8;

impl TrapFrame {
    /// Did this trap interrupt U-mode (user) code?
    pub fn from_user(&self) -> bool {
        self.sstatus & SSTATUS_SPP == 0
    }
}

pub fn init() {
    // trap.S reads sscratch == 0 as "trap came from S-mode".
    arch::clear_sscratch();
    // SAFETY: __trap_entry is the 16-byte-aligned routine in trap.S that
    // saves and restores the full register state around trap_handler.
    unsafe { arch::write_stvec(__trap_entry as unsafe extern "C" fn() as usize) };
}

fn exception_name(code: usize) -> &'static str {
    match code {
        0 => "instruction address misaligned",
        1 => "instruction access fault",
        2 => "illegal instruction",
        3 => "breakpoint",
        4 => "load address misaligned",
        5 => "load access fault",
        6 => "store address misaligned",
        7 => "store access fault",
        8 => "environment call from U-mode",
        9 => "environment call from S-mode",
        12 => "instruction page fault",
        13 => "load page fault",
        15 => "store page fault",
        _ => "unknown exception",
    }
}

/// Called by `trap.S` with interrupts disabled (the hart clears sstatus.SIE
/// on trap entry). A timer interrupt may switch to another task inside
/// `on_timer_interrupt`; this function then returns only when the
/// interrupted task is scheduled again.
#[no_mangle]
extern "C" fn trap_handler(tf: &mut TrapFrame) {
    let scause = arch::read_scause();
    let code = scause & !arch::SCAUSE_INTERRUPT;
    if scause & arch::SCAUSE_INTERRUPT != 0 {
        match code {
            arch::IRQ_S_TIMER => scheduler::on_timer_interrupt(),
            _ => kwarn!("ignoring unexpected interrupt {}", code),
        }
    } else if code == EXC_ECALL_FROM_U {
        // System call: resume after the 4-byte ecall instruction.
        tf.sepc += 4;
        crate::user::syscall(tf);
    } else if tf.from_user() {
        // A user program did something it may not (e.g. a privileged
        // instruction): stop that program, keep the kernel running.
        crate::user::kill_current(exception_name(code), tf.sepc, arch::read_stval());
    } else {
        panic!(
            "unhandled exception: {} (scause={:#x}) at sepc={:#x}, stval={:#x}",
            exception_name(code),
            scause,
            tf.sepc,
            arch::read_stval()
        );
    }
}

kernel/src/task/mod.rs.text:
//! Layer 3 — task representation (the task control block).

mod stack;

use alloc::boxed::Box;

use microos_core::sched::{Leave, SchedInfo, Tid};

pub use stack::{KernelStack, STACK_SIZE};

core::arch::global_asm!(include_str!("switch.S"));

extern "C" {
    /// Save callee-saved registers into `save`, load them from `load`, and
    /// continue at `load.ra` on `load.sp`.
    pub fn __switch_context(save: *mut Context, load: *const Context);
}

/// Callee-saved register state; layout must match `switch.S`.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
pub struct Context {
    pub ra: usize,
    pub sp: usize,
    pub s: [usize; 12],
}

impl Context {
    pub const fn zero() -> Self {
        Self { ra: 0, sp: 0, s: [0; 12] }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TaskState {
    Ready,
    Running,
    Blocked,
    Terminated,
}

impl TaskState {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Ready => "READY",
            Self::Running => "RUNNING",
            Self::Blocked => "BLOCKED",
            Self::Terminated => "TERMINATED",
        }
    }
}

pub type Entry = Box<dyn FnOnce() + Send + 'static>;

/// Per-task measurements, all timestamps in microseconds.
#[derive(Clone, Copy, Debug, Default)]
pub struct TaskMetrics {
    pub arrived: bool,
    pub arrival_us: u64,
    pub first_run_us: Option<u64>,
    pub finish_us: u64,
    pub cpu_ticks: u64,
    /// Exact CPU time in raw timebase units (100 ns).
    pub cpu_raw: u64,
    pub dispatches: u64,
    pub preemptions: u64,
    pub yields: u64,
    pub blocks: u64,
    pub ready_since_us: u64,
    pub wait_us: u64,
    pub max_wait_us: u64,
}

pub struct Task {
    pub tid: Tid,
    pub name: &'static str,
    pub state: TaskState,
    /// Saved registers while the task is not running.
    pub ctx: Context,
    pub stack: KernelStack,
    /// The task body; taken (and run) on first dispatch.
    pub entry: Option<Entry>,
    pub sched: SchedInfo,
    /// Ticks allowed in the current slice / ticks used so far.
    pub quantum: u32,
    pub slice_used: u32,
    /// Why the task last left (or is about to leave) the CPU.
    pub leave: Leave,
    /// Tick at which a sleeping task becomes ready.
    pub wake_at: u64,
    /// Set by Ctrl-C in the shell; programs check it cooperatively.
    pub cancel: bool,
    /// Exact CPU time (raw units) at the start of the current fairness interval
    /// (None if the task arrived during the interval, so it is not counted for it).
    pub fair_snap: Option<u64>,
    /// Time CSR value when the task last started running.
    pub run_since_raw: u64,
    pub m: TaskMetrics,
}

impl Task {
    /// A fresh task whose first dispatch "returns" into `trampoline` on its
    /// own stack.
    pub fn new(tid: Tid, name: &'static str, prio: u8, entry: Entry, stack: KernelStack, trampoline: usize) -> Self {
        let ctx = Context { ra: trampoline, sp: stack.top(), s: [0; 12] };
        Self {
            tid,
            name,
            state: TaskState::Blocked,
            ctx,
            stack,
            entry: Some(entry),
            sched: SchedInfo::new(tid, prio),
            quantum: 0,
            slice_used: 0,
            leave: Leave::Yielded,
            wake_at: 0,
            cancel: false,
            fair_snap: None,
            run_since_raw: 0,
            m: TaskMetrics::default(),
        }
    }
}

kernel/src/task/stack.rs.text:
//! Heap-allocated kernel stacks with overflow detection and usage measurement.
//!
//! On creation the whole stack is painted with a byte pattern and a canary
//! word is written at the lowest address. The scheduler checks the canary
//! every time the task leaves the CPU (overflow detection), and on exit the
//! untouched paint tells us the task's peak stack usage.

use alloc::alloc::{alloc, dealloc};
use core::alloc::Layout;
use core::ptr::{self, NonNull};

pub const STACK_SIZE: usize = 16 * 1024;
const PAINT: u8 = 0x5A;
const CANARY: u64 = 0x57AC_C0DE_DEAD_10CC;
const ALIGN: usize = 16;

pub struct KernelStack {
    base: NonNull<u8>,
    size: usize,
}

// SAFETY: the stack memory is exclusively owned by this value.
unsafe impl Send for KernelStack {}

impl KernelStack {
    pub fn new(size: usize) -> Option<Self> {
        let layout = Layout::from_size_align(size, ALIGN).ok()?;
        // SAFETY: layout has non-zero size.
        let base = NonNull::new(unsafe { alloc(layout) })?;
        // SAFETY: we own the `size` freshly allocated bytes; the canary write
        // is 8-byte aligned because the block is 16-byte aligned.
        unsafe {
            ptr::write_bytes(base.as_ptr(), PAINT, size);
            (base.as_ptr() as *mut u64).write(CANARY);
        }
        Some(Self { base, size })
    }

    /// Initial stack pointer: the (16-byte-aligned) end of the block.
    pub fn top(&self) -> usize {
        self.base.as_ptr() as usize + self.size
    }

    pub fn canary_intact(&self) -> bool {
        // SAFETY: the first 8 bytes of our allocation, aligned.
        unsafe { (self.base.as_ptr() as *const u64).read_volatile() == CANARY }
    }

    /// Peak bytes ever used. Call only while the task is not running.
    pub fn high_water(&self) -> usize {
        // SAFETY: our allocation, skipping the canary word; the owning task is
        // not running, so nothing writes the memory concurrently.
        let body = unsafe { core::slice::from_raw_parts(self.base.as_ptr().add(8), self.size - 8) };
        let untouched = body.iter().take_while(|&&b| b == PAINT).count();
        self.size - 8 - untouched
    }
}

impl Drop for KernelStack {
    fn drop(&mut self) {
        // SAFETY: allocated in `new` with exactly this layout.
        unsafe { dealloc(self.base.as_ptr(), Layout::from_size_align_unchecked(self.size, ALIGN)) };
    }
}

kernel/src/sync/irq.rs.text:
//! Interrupt-safe critical sections for kernel-internal data.
//!
//! On this single-hart kernel the only source of concurrency inside the
//! kernel is the timer interrupt, so "disable interrupts, then take the
//! lock" is both necessary and sufficient. The atomic flag is kept to detect
//! re-entrancy bugs: if the flag is already set while interrupts are off on
//! the only hart, the holder can never run again, so we panic with the lock's
//! name instead of hanging silently.

use core::cell::UnsafeCell;
use core::ops::{Deref, DerefMut};
use core::sync::atomic::{AtomicBool, Ordering};

use crate::arch;

/// Disables interrupts on creation and restores the previous state on drop,
/// so guards nest correctly.
pub struct IrqGuard {
    was_enabled: bool,
}

impl IrqGuard {
    pub fn new() -> Self {
        let was_enabled = arch::intr_enabled();
        arch::intr_off();
        Self { was_enabled }
    }
}

impl Drop for IrqGuard {
    fn drop(&mut self) {
        if self.was_enabled {
            arch::intr_on();
        }
    }
}

pub struct IrqSpinLock<T> {
    name: &'static str,
    locked: AtomicBool,
    data: UnsafeCell<T>,
}

// SAFETY: `data` is reachable only through a guard; a guard exists only while
// `locked` is set and interrupts are disabled, so neither an interrupt
// handler nor (on a multi-hart system) another hart can access it concurrently.
unsafe impl<T: Send> Sync for IrqSpinLock<T> {}
unsafe impl<T: Send> Send for IrqSpinLock<T> {}

impl<T> IrqSpinLock<T> {
    pub const fn new(name: &'static str, value: T) -> Self {
        Self { name, locked: AtomicBool::new(false), data: UnsafeCell::new(value) }
    }

    pub fn lock(&self) -> IrqSpinGuard<'_, T> {
        let irq = IrqGuard::new();
        if self.locked.swap(true, Ordering::Acquire) {
            panic!("deadlock: IrqSpinLock '{}' re-acquired while already held", self.name);
        }
        IrqSpinGuard { lock: self, _irq: irq }
    }

    /// Like `lock`, but returns `None` instead of panicking if held (used by
    /// the panic handler).
    pub fn try_lock(&self) -> Option<IrqSpinGuard<'_, T>> {
        let irq = IrqGuard::new();
        if self.locked.swap(true, Ordering::Acquire) {
            return None;
        }
        Some(IrqSpinGuard { lock: self, _irq: irq })
    }
}

/// Field order matters: `Drop::drop` releases the flag first, then `_irq` is
/// dropped and re-enables interrupts.
pub struct IrqSpinGuard<'a, T> {
    lock: &'a IrqSpinLock<T>,
    _irq: IrqGuard,
}

impl<T> Deref for IrqSpinGuard<'_, T> {
    type Target = T;
    fn deref(&self) -> &T {
        // SAFETY: we hold the lock.
        unsafe { &*self.lock.data.get() }
    }
}

impl<T> DerefMut for IrqSpinGuard<'_, T> {
    fn deref_mut(&mut self) -> &mut T {
        // SAFETY: we hold the lock exclusively.
        unsafe { &mut *self.lock.data.get() }
    }
}

impl<T> Drop for IrqSpinGuard<'_, T> {
    fn drop(&mut self) {
        self.lock.locked.store(false, Ordering::Release);
    }
}

