//! Layer 7 — synchronization.
//!
//! | primitive      | waits by            | used for                                  |
//! |----------------|---------------------|-------------------------------------------|
//! | `IrqSpinLock`  | masking interrupts  | kernel-internal data (scheduler, heap, console) |
//! | `SpinLock`     | busy-wait or yield  | short task-level critical sections        |
//! | `Mutex`        | blocking (sleeping) | task-level critical sections of any length|
//! | `Semaphore`    | blocking (sleeping) | counting resources, producer/consumer     |

mod irq;
mod mutex;
mod semaphore;

pub use irq::{IrqGuard, IrqSpinLock};
pub use microos_core::spin::SpinLock;
pub use mutex::Mutex;
pub use semaphore::Semaphore;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SyncError {
    /// Unlock of a mutex that is not locked.
    NotLocked,
    /// Unlock by a task that does not own the mutex.
    NotOwner,
}

kernel/src/sync/mutex.rs.text:
//! Blocking mutex with FIFO hand-off.
//!
//! A task that finds the mutex held is put on the mutex's wait queue and
//! BLOCKED, so it uses no CPU while waiting. `unlock` hands ownership
//! directly to the longest waiter before waking it, so there is no
//! "thundering herd" and no barging: waiters acquire in arrival order.

use alloc::collections::VecDeque;
use core::cell::UnsafeCell;
use core::ops::{Deref, DerefMut};

use microos_core::sched::Tid;

use super::{IrqGuard, IrqSpinLock, SyncError};
use crate::{scheduler, timer};

#[derive(Clone, Copy, Debug, Default)]
pub struct LockStats {
    pub acquisitions: u64,
    pub contended: u64,
    pub total_wait_us: u64,
    pub max_wait_us: u64,
    pub max_waiters: usize,
}

impl LockStats {
    const fn new() -> Self {
        Self { acquisitions: 0, contended: 0, total_wait_us: 0, max_wait_us: 0, max_waiters: 0 }
    }
}

struct State {
    owner: Option<Tid>,
    waiters: VecDeque<(Tid, u64)>,
    stats: LockStats,
}

pub struct Mutex<T> {
    name: &'static str,
    state: IrqSpinLock<State>,
    data: UnsafeCell<T>,
}

// SAFETY: `data` is reachable only through a MutexGuard, which exists only
// for the single task recorded as `owner` (updated under `state`).
unsafe impl<T: Send> Sync for Mutex<T> {}
unsafe impl<T: Send> Send for Mutex<T> {}

impl<T> Mutex<T> {
    pub const fn new(name: &'static str, value: T) -> Self {
        Self {
            name,
            state: IrqSpinLock::new("mutex", State { owner: None, waiters: VecDeque::new(), stats: LockStats::new() }),
            data: UnsafeCell::new(value),
        }
    }

    /// Acquire, blocking the calling task while another task owns the mutex.
    /// Must be called from a task.
    pub fn lock(&self) -> MutexGuard<'_, T> {
        let me = scheduler::current_tid().expect("Mutex::lock called outside a task");
        // Interrupts stay off from the ownership check until we have switched
        // away, so the owner cannot unlock (and fail to find us) in between.
        let _irq = IrqGuard::new();
        {
            let mut st = self.state.lock();
            st.stats.acquisitions += 1;
            match st.owner {
                None => {
                    st.owner = Some(me);
                    return MutexGuard { mutex: self };
                }
                Some(owner) if owner == me => {
                    panic!("mutex '{}': task {} locked it twice (self-deadlock)", self.name, me)
                }
                Some(_) => {
                    st.stats.contended += 1;
                    kdebug!("mutex '{}': tid {} blocks behind tid {:?}", self.name, me, st.owner);
                    st.waiters.push_back((me, timer::now_us()));
                    st.stats.max_waiters = st.stats.max_waiters.max(st.waiters.len());
                    scheduler::mark_current_blocked();
                }
            }
        }
        scheduler::switch_to_scheduler();
        // We only run again after unlock() made us the owner.
        debug_assert_eq!(self.state.lock().owner, Some(me));
        MutexGuard { mutex: self }
    }

    /// Release the mutex as the current task.
    ///
    /// # Safety
    /// The caller must not hold a `MutexGuard` for this mutex (the guard
    /// would then outlive the ownership it represents). This exists so tests
    /// can demonstrate that invalid unlocks are rejected.
    pub unsafe fn force_unlock(&self) -> Result<(), SyncError> {
        self.unlock_as(scheduler::current_tid())
    }

    fn unlock_as(&self, me: Option<Tid>) -> Result<(), SyncError> {
        let next = {
            let mut st = self.state.lock();
            match st.owner {
                None => return Err(SyncError::NotLocked),
                Some(owner) if Some(owner) != me => return Err(SyncError::NotOwner),
                Some(_) => {}
            }
            match st.waiters.pop_front() {
                Some((tid, since)) => {
                    let waited = timer::now_us().saturating_sub(since);
                    st.stats.total_wait_us += waited;
                    st.stats.max_wait_us = st.stats.max_wait_us.max(waited);
                    st.owner = Some(tid);
                    Some(tid)
                }
                None => {
                    st.owner = None;
                    None
                }
            }
        };
        if let Some(tid) = next {
            scheduler::wake(tid);
        }
        Ok(())
    }

    pub fn stats(&self) -> LockStats {
        self.state.lock().stats
    }

    /// Consume the mutex; ownership of `self` proves nobody else can hold it.
    pub fn into_inner(self) -> T {
        self.data.into_inner()
    }
}

pub struct MutexGuard<'a, T> {
    mutex: &'a Mutex<T>,
}

impl<T> Deref for MutexGuard<'_, T> {
    type Target = T;
    fn deref(&self) -> &T {
        // SAFETY: the guard proves the current task owns the mutex.
        unsafe { &*self.mutex.data.get() }
    }
}

impl<T> DerefMut for MutexGuard<'_, T> {
    fn deref_mut(&mut self) -> &mut T {
        // SAFETY: the guard proves exclusive ownership.
        unsafe { &mut *self.mutex.data.get() }
    }
}

impl<T> Drop for MutexGuard<'_, T> {
    fn drop(&mut self) {
        if let Err(e) = self.mutex.unlock_as(scheduler::current_tid()) {
            panic!("mutex '{}': guard release failed: {:?}", self.mutex.name, e);
        }
    }
}

kernel/src/sync/semaphore.rs.text:
//! Counting semaphore with a FIFO wait queue. `signal` passes the permit
//! straight to the oldest waiter if there is one, otherwise banks it.

use alloc::collections::VecDeque;

use microos_core::sched::Tid;

use super::{IrqGuard, IrqSpinLock};
use crate::scheduler;

#[derive(Clone, Copy, Debug, Default)]
pub struct SemStats {
    pub waits: u64,
    /// `wait` calls that had to block.
    pub blocked: u64,
    pub signals: u64,
}

struct State {
    permits: usize,
    waiters: VecDeque<Tid>,
    stats: SemStats,
}

pub struct Semaphore {
    name: &'static str,
    state: IrqSpinLock<State>,
}

impl Semaphore {
    pub const fn new(name: &'static str, permits: usize) -> Self {
        Self {
            name,
            state: IrqSpinLock::new(
                "semaphore",
                State { permits, waiters: VecDeque::new(), stats: SemStats { waits: 0, blocked: 0, signals: 0 } },
            ),
        }
    }

    /// P / down: take a permit, blocking until one is available.
    pub fn wait(&self) {
        let me = scheduler::current_tid().expect("Semaphore::wait called outside a task");
        let _irq = IrqGuard::new();
        {
            let mut st = self.state.lock();
            st.stats.waits += 1;
            if st.permits > 0 {
                st.permits -= 1;
                return;
            }
            st.stats.blocked += 1;
            kdebug!("semaphore '{}': tid {} blocks (no permits)", self.name, me);
            st.waiters.push_back(me);
            scheduler::mark_current_blocked();
        }
        scheduler::switch_to_scheduler();
    }

    /// V / up: release a permit, waking the oldest waiter if any.
    pub fn signal(&self) {
        let waiter = {
            let mut st = self.state.lock();
            st.stats.signals += 1;
            let w = st.waiters.pop_front();
            if w.is_none() {
                st.permits += 1;
            }
            w
        };
        if let Some(tid) = waiter {
            scheduler::wake(tid);
        }
    }

    pub fn stats(&self) -> SemStats {
        self.state.lock().stats
    }
}

kernel/src/memory/mod.rs.text:
//! Layer 8 — memory management: the kernel heap.
//!
//! The region after the kernel image (`__heap_start`, from the linker script)
//! is handed to a first-fit [`FreeListAllocator`] and registered as Rust's
//! `#[global_allocator]`, so `Box`, `Vec`, `Arc` and task stacks all come
//! from it.

use core::alloc::{GlobalAlloc, Layout};

use microos_core::mem::{AllocStats, Fit, FreeError, FreeListAllocator, RegionAllocator};

use crate::sync::IrqSpinLock;

pub const HEAP_SIZE: usize = 16 * 1024 * 1024;

extern "C" {
    static __kernel_start: u8;
    static __kernel_end: u8;
    static __heap_start: u8;
}

pub struct KernelHeap {
    inner: IrqSpinLock<FreeListAllocator>,
}

#[global_allocator]
static HEAP: KernelHeap = KernelHeap { inner: IrqSpinLock::new("heap", FreeListAllocator::empty(Fit::First)) };

/// Hand the heap region to the allocator. Returns (start, size).
pub fn init() -> (usize, usize) {
    let start = core::ptr::addr_of!(__heap_start) as usize;
    // SAFETY: [start, start + HEAP_SIZE) lies in RAM above the kernel image
    // (see linker.ld; QEMU runs with 128 MiB) and is used by nothing else.
    unsafe { HEAP.inner.lock().init(start, HEAP_SIZE) };
    (start, HEAP_SIZE)
}

/// Kernel image bounds (start, end).
pub fn kernel_image() -> (usize, usize) {
    (core::ptr::addr_of!(__kernel_start) as usize, core::ptr::addr_of!(__kernel_end) as usize)
}

pub fn stats() -> AllocStats {
    HEAP.inner.lock().stats()
}

/// Heap map: how full each of `out.len()` equal slices of the heap is
/// (0 free .. 255 full), read from the real free list. Allocates nothing.
pub fn occupancy(out: &mut [u8]) {
    HEAP.inner.lock().occupancy(out);
}

/// Free through the kernel heap and report whether the request was accepted
/// (`GlobalAlloc::dealloc` cannot return an error).
///
/// # Safety
/// If `ptr` is a live heap allocation it must not be used afterwards.
pub unsafe fn checked_free(ptr: *mut u8, layout: Layout) -> Result<(), FreeError> {
    HEAP.inner.lock().dealloc(ptr, layout)
}

// SAFETY: blocks returned by `alloc` are inside the heap region, aligned as
// requested (FreeListAllocator::place), and never handed out twice while
// live; the IrqSpinLock serialises every call, including ones made from the
// timer interrupt path. `dealloc` validates the pointer before reusing it.
unsafe impl GlobalAlloc for KernelHeap {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let p = self.inner.lock().alloc(layout);
        if p.is_null() {
            kwarn!("heap: allocation of {} bytes (align {}) failed", layout.size(), layout.align());
        }
        p
    }

    // Safety: GlobalAlloc's contract (ptr came from this allocator with this
    // layout); a pointer that breaks it is detected and refused, not freed.
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        if let Err(e) = self.inner.lock().dealloc(ptr, layout) {
            kerror!("heap: rejected free of {:p}: {:?}", ptr, e);
        }
    }
}

kernel/src/boot/mod.rs.text:
//! Layer 1 — boot: the assembly entry stub and reading the kernel command line.

use microos_core::{args::BootArgs, fdt};

core::arch::global_asm!(include_str!("entry.S"));

/// Read `/chosen/bootargs` from the device tree the firmware handed us.
pub fn boot_args(dtb: usize) -> BootArgs<'static> {
    if dtb == 0 {
        return BootArgs::new("");
    }
    // SAFETY: OpenSBI passes the address of a valid DTB in RAM. We read the
    // fixed-size header first and only then a slice of the declared size;
    // the DTB is never written, so a 'static shared borrow is sound.
    let blob = unsafe {
        let header = core::slice::from_raw_parts(dtb as *const u8, fdt::header_len());
        match fdt::total_size(header) {
            Some(size) => core::slice::from_raw_parts(dtb as *const u8, size),
            None => return BootArgs::new(""),
        }
    };
    BootArgs::new(fdt::find_bootargs(blob).unwrap_or(""))
}

kernel/src/timer/mod.rs.text:
//! Layer 6 — periodic timer. Each tick re-arms the SBI timer and advances a
//! global tick counter; the scheduler decides what a tick means.

use core::sync::atomic::{AtomicU64, Ordering::Relaxed};

use crate::{arch, drivers::sbi};

/// Frequency of the `time` CSR on QEMU virt.
pub const TIMEBASE_HZ: u64 = 10_000_000;
const UNITS_PER_US: u64 = TIMEBASE_HZ / 1_000_000;

static TICKS: AtomicU64 = AtomicU64::new(0);
static INTERVAL: AtomicU64 = AtomicU64::new(0);

pub fn init(tick_us: u64) {
    INTERVAL.store(tick_us.max(10) * UNITS_PER_US, Relaxed);
    arch::enable_timer_interrupt();
    arm();
}

fn arm() {
    sbi::set_timer(arch::read_time() + INTERVAL.load(Relaxed));
}

/// Acknowledge a timer interrupt: schedule the next one and count the tick.
pub fn handle_tick() -> u64 {
    arm();
    TICKS.fetch_add(1, Relaxed) + 1
}

pub fn ticks() -> u64 {
    TICKS.load(Relaxed)
}

pub fn now_us() -> u64 {
    arch::read_time() / UNITS_PER_US
}

/// Raw timebase units (100 ns each) for fine-grained measurements.
pub fn now_raw() -> u64 {
    arch::read_time()
}

/// Length of one timer tick in microseconds.
pub fn tick_us() -> u64 {
    (INTERVAL.load(Relaxed) / UNITS_PER_US).max(1)
}

pub fn raw_to_ns(raw: u64) -> u64 {
    raw * (1_000_000_000 / TIMEBASE_HZ)
}

kernel/src/shell/mod.rs.text:
//! Interactive command shell on the serial console (`test=shell`).
//!
//! The shell is itself a task (priority 0). It polls the UART once per
//! timer tick and sleeps in between, so programs it starts get the CPU.
//! Foreground programs are waited for (Ctrl-C asks them to stop);
//! programs started with a trailing `&` run in the background.
//!
//! With `monitor=1` a second task emits a `#T SNAP` line every
//! `monitor_ms` (default 250) describing all tasks, the scheduler and the
//! heap; the web front end (`frontend/server.py`) draws its live views
//! from these.

use alloc::{string::String, vec::Vec};
use core::fmt::Write;
use core::sync::atomic::{AtomicBool, Ordering::Relaxed};

use microos_core::args::BootArgs;
use microos_core::sched::PolicyKind;

use crate::kernel::console::{self, Level};
use crate::scheduler::{self, BurstInfo, Config, SpawnOpts, MAX_TASKS};
use crate::{drivers, memory, programs, sys, timer};

const CTRL_C: u8 = 0x03;
const BACKSPACE: u8 = 0x08;
const DELETE: u8 = 0x7f;

/// Set when the shell exits, so the monitor task stops too.
static SHELL_DONE: AtomicBool = AtomicBool::new(false);
/// Running under the web panel (`monitor=1`): start the console on a clean screen.
static PANEL_MODE: AtomicBool = AtomicBool::new(false);

pub fn run(args: &BootArgs) -> u32 {
    let policy = args.get("policy").and_then(PolicyKind::parse).unwrap_or(PolicyKind::RoundRobin);
    let quantum = args.get_u64("quantum").unwrap_or(4).clamp(1, 1000) as u32;
    // Trace events would flood the terminal; `trace on` re-enables them.
    console::set_trace(args.flag("trace", false));
    SHELL_DONE.store(false, Relaxed);
    // Burst-ordered policies cannot be told a program's CPU demand here,
    // so the kernel predicts it from each task's history.
    let bursts = if policy.needs_bursts() { BurstInfo::Predicted } else { BurstInfo::Oracle };
    scheduler::begin(Config { label: "shell".into(), policy, quantum, preemptive: true, bursts, ..Config::default() });
    scheduler::spawn("shell", SpawnOpts { prio: 0, ..SpawnOpts::default() }, shell_main).expect("could not start the shell");
    PANEL_MODE.store(args.flag("monitor", false), Relaxed);
    if args.flag("monitor", false) {
        let interval_ms = args.get_u64("monitor_ms").unwrap_or(250).max(20);
        scheduler::spawn("monitor", SpawnOpts { prio: 0, ..SpawnOpts::default() }, move || monitor(interval_ms))
            .expect("could not start the monitor");
    }
    let r = scheduler::run();
    kinfo!("shell session over: {} tasks ran, {} dispatches, {} preemptions", r.tasks.len(), r.stats.dispatches, r.stats.preemptions);
    0
}

// Basic ANSI colours: a real terminal shows its own palette, and the web
// panel maps them to the NEXUS theme (coral accent, celadon, chalk).
const PURPLE: &str = "\x1b[31m"; // accent: NEXUS coral
const GREEN: &str = "\x1b[32m";
const DIM: &str = "\x1b[90m";
const BOLD: &str = "\x1b[1m";
const RESET: &str = "\x1b[0m";
const PINK: &str = "\x1b[33m"; // gold
const LINE: &str = "\x1b[90m";

/// A horizontal rule between sections of output.
fn rule() {
    println!("{LINE}{}{RESET}", "\u{2500}".repeat(76));
}

/// Checklist of what the kernel actually brought up, read from live state.
fn banner() {
    let ok = |text: core::fmt::Arguments| println!("{GREEN}[\u{2713}]{RESET}    {}", text);
    let h = memory::stats();
    if PANEL_MODE.load(Relaxed) {
        // Firmware and kernel boot logs scroll into the terminal history.
        print!("\x1b[2J\x1b[H");
    } else {
        println!();
    }
    println!("{PURPLE}[BOOT]{RESET} NEXUS \u{00b7} Micro-OS v{} (riscv64, S-mode, {})", env!("CARGO_PKG_VERSION"), drivers::sbi::impl_name());
    println!("{PURPLE}[BOOT]{RESET} Kernel subsystems:");
    ok(format_args!("Trap vector installed (timer interrupts on)"));
    ok(format_args!("Kernel heap ready ({} MiB, first-fit free list)", h.capacity >> 20));
    ok(format_args!("Timer running ({} us per tick)", timer::tick_us()));
    if let Some((policy, quantum, preemptive, _, _)) = scheduler::run_info() {
        let mode = if preemptive { "preemptive" } else { "cooperative" };
        ok(format_args!("Scheduler initialized ({}, quantum {} ticks, {})", policy, quantum, mode));
    }
    ok(format_args!("Starting tasks..."));
    for t in scheduler::snapshot() {
        println!("         {DIM}->{RESET} {} (pid: {})", t.name, t.tid);
    }
    println!("{GREEN}[\u{2713}]{RESET}    {BOLD}NEXUS is ready.{RESET} {PINK}\u{25a0}{RESET}  {DIM}type 'help' for commands, 'progs' for programs{RESET}");
    rule();
}

fn prompt() {
    print!("{PURPLE}{BOLD}nexus@os{RESET}:{GREEN}~{RESET}$ ");
}

fn shell_main() {
    banner();
    let mut line = String::new();
    loop {
        prompt();
        read_line(&mut line);
        let words: Vec<&str> = line.split_whitespace().collect();
        let Some((&cmd, rest)) = words.split_first() else { continue };
        match cmd {
            "help" | "?" => help(),
            "progs" | "ls" => list_programs(),
            "run" => run_program(rest),
            "ps" => ps(),
            "top" => top(),
            "sched" => sched(),
            "mem" => mem(),
            "sysinfo" => sysinfo(),
            "uptime" => println!("up {} ms, {} timer ticks of {} us", sys::uptime_ms(), timer::ticks(), timer::tick_us()),
            "kill" => kill(rest),
            "trace" => set_trace(rest),
            "log" => set_log(rest),
            "echo" => println!("{}", rest.join(" ")),
            "clear" => print!("\x1b[2J\x1b[H"),
            "exit" | "shutdown" | "poweroff" => break,
            name if programs::find(name).is_some() => run_program(&words),
            other => println!("unknown command '{}' (try 'help')", other),
        }
    }
    SHELL_DONE.store(true, Relaxed);
    let others = scheduler::snapshot().iter().filter(|t| t.name != "shell" && t.name != "monitor").count();
    if others > 0 {
        println!("waiting for {} background task(s) to finish...", others);
    }
    println!("bye");
}

/// Live monitor task: one machine-readable snapshot per interval.
fn monitor(interval_ms: u64) {
    let per_map = (1000 / interval_ms.max(1)).max(1);
    let mut n = 0u64;
    while !SHELL_DONE.load(Relaxed) {
        emit_snapshot();
        if n % per_map == 0 {
            emit_heap_map();
        }
        n += 1;
        sys::sleep_ms(interval_ms);
    }
    emit_snapshot();
}

/// Ticks between keyboard polls while the shell waits for input.
const KEY_POLL_TICKS: u64 = 10;

/// Slices in the heap map: 16 MiB / 128 = 128 KiB each.
const HEAP_MAP_SLICES: usize = 128;

/// `#T ... HEAPMAP slices=128 slice_bytes=N map=<hex byte per slice>`: how
/// full each slice of the heap is (00 free .. ff full), from the free list.
fn emit_heap_map() {
    struct Hex<'a>(&'a [u8]);
    impl core::fmt::Display for Hex<'_> {
        fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
            self.0.iter().try_for_each(|b| write!(f, "{:02x}", b))
        }
    }
    let mut map = [0u8; HEAP_MAP_SLICES];
    memory::occupancy(&mut map);
    let cap = memory::stats().capacity;
    console::trace_always(
        "HEAPMAP",
        format_args!("slices={} slice_bytes={} map={}", HEAP_MAP_SLICES, cap.div_ceil(HEAP_MAP_SLICES), Hex(&map)),
    );
}

/// `#T ... SNAP key=value ... tasks=tid:name:state:prio:level:cpu:dispatches;...`
fn emit_snapshot() {
    let Some((policy, quantum, _, st, ready)) = scheduler::run_info() else { return };
    let h = memory::stats();
    let mut tasks = String::new();
    for t in scheduler::snapshot() {
        let sep = if tasks.is_empty() { "" } else { ";" };
        let _ = write!(
            tasks, "{}{}:{}:{}:{}:{}:{}:{}",
            sep, t.tid, t.name, t.state.as_str(), t.prio, t.level, t.cpu_ticks, t.dispatches
        );
    }
    console::trace_always(
        "SNAP",
        format_args!(
            "ticks={} idle={} disp={} pre={} yld={} blk={} wake={} ready={} policy={} q={} tick_us={} \
             heap_used={} heap_peak={} heap_cap={} free_blocks={} largest={} frag_bp={} allocs={} frees={} tasks={}",
            st.ticks, st.idle_ticks, st.dispatches, st.preemptions, st.yields, st.blocks, st.wakeups, ready,
            policy, quantum, timer::tick_us(), h.bytes_in_use, h.peak_bytes, h.capacity, h.free_blocks,
            h.largest_free, h.fragmentation_bp(), h.allocs, h.frees, tasks
        ),
    );
}

/// Read one line with echo and backspace. Ctrl-C discards the line.
fn read_line(line: &mut String) {
    line.clear();
    loop {
        match console::read_byte() {
            // Nothing typed: check again in 10 ms. Polling every 1 ms tick
            // woke the shell 1000 times a second for no work.
            None => scheduler::sleep_ticks(KEY_POLL_TICKS),
            Some(b'\r' | b'\n') => {
                println!();
                return;
            }
            Some(BACKSPACE | DELETE) => {
                if line.pop().is_some() {
                    print!("\x08 \x08");
                }
            }
            Some(CTRL_C) => {
                println!("^C");
                line.clear();
                return;
            }
            Some(b) if (0x20..0x7f).contains(&b) => {
                line.push(b as char);
                print!("{}", b as char);
            }
            Some(_) => {} // ignore other control bytes / escape sequences
        }
    }
}

fn help() {
    const LEFT: [(&str, &str); 8] = [
        ("help", "show this help"),
        ("progs", "list programs"),
        ("run [-p N] PROG [&]", "run a program"),
        ("PROG ARGS [&]", "same as run PROG"),
        ("ps", "list tasks"),
        ("top", "live task view"),
        ("kill PID", "ask a task to stop"),
        ("exit", "power off"),
    ];
    const RIGHT: [(&str, &str); 8] = [
        ("sched", "scheduler statistics"),
        ("mem", "kernel heap usage"),
        ("sysinfo", "system information"),
        ("uptime", "time since boot"),
        ("trace on|off", "kernel trace events"),
        ("log LEVEL", "error|warn|info|debug"),
        ("echo TEXT", "print text"),
        ("clear", "clear the screen"),
    ];
    println!("Available commands:");
    rule();
    for ((lc, ld), (rc, rd)) in LEFT.iter().zip(RIGHT.iter()) {
        println!(
            "  {PURPLE}{:<20}{RESET}{DIM}-{RESET} {:<20} {DIM}|{RESET}  {PURPLE}{:<13}{RESET}{DIM}-{RESET} {}",
            lc, ld, rc, rd
        );
    }
    rule();
    println!("{DIM}N = priority 0 (high) to 7 (low); '&' runs in the background; Ctrl-C stops the foreground program.{RESET}");
}

fn sysinfo() {
    let (major, minor) = drivers::sbi::spec_version();
    let h = memory::stats();
    let (ks, ke) = memory::kernel_image();
    let row = |k: &str, v: core::fmt::Arguments| println!("  {PURPLE}{:<12}{RESET} {}", k, v);
    row("os", format_args!("NEXUS (Micro-OS v{})", env!("CARGO_PKG_VERSION")));
    row("machine", format_args!("QEMU virt, 1 RISC-V hart (riscv64gc), supervisor mode"));
    row("firmware", format_args!("{} (SBI v{}.{})", drivers::sbi::impl_name(), major, minor));
    row("kernel", format_args!("{:#x}..{:#x} ({} KiB)", ks, ke, (ke - ks) / 1024));
    row("heap", format_args!("{} MiB first-fit free list, {} B in use", h.capacity >> 20, h.bytes_in_use));
    row("timer", format_args!("{} us per tick, {} ticks so far", timer::tick_us(), timer::ticks()));
    if let Some((policy, quantum, _, _, _)) = scheduler::run_info() {
        row("scheduler", format_args!("{} with a {}-tick quantum, max {} tasks", policy, quantum, MAX_TASKS));
    }
    row("uptime", format_args!("{} ms", sys::uptime_ms()));
}

fn list_programs() {
    for p in programs::PROGRAMS {
        println!("  {:<26} {}", p.usage, p.about);
    }
}

fn run_program(words: &[&str]) {
    let mut words: Vec<&str> = words.to_vec();
    let mut background = false;
    if let Some(last) = words.last_mut() {
        if *last == "&" {
            words.pop();
            background = true;
        } else if let Some(stripped) = last.strip_suffix('&') {
            *last = stripped;
            background = true;
        }
    }
    let mut prio = 4u8;
    if words.first() == Some(&"-p") {
        match words.get(1).and_then(|p| p.parse::<u8>().ok()) {
            Some(p) if p <= 7 => prio = p,
            _ => {
                println!("run: -p needs a priority 0-7");
                return;
            }
        }
        words.drain(..2);
    }
    let Some((&name, args)) = words.split_first() else {
        println!("usage: run [-p N] PROG [ARGS...] [&]");
        return;
    };
    let Some(prog) = programs::find(name) else {
        println!("run: no program '{}' (try 'progs')", name);
        return;
    };

    let owned: Vec<String> = args.iter().map(|a| String::from(*a)).collect();
    let (pname, main) = (prog.name, prog.main);
    let spawned = scheduler::spawn(pname, SpawnOpts { prio, ..SpawnOpts::default() }, move || {
        let args: Vec<&str> = owned.iter().map(String::as_str).collect();
        let code = main(&args);
        println!("[{} pid {} exited with code {}]", pname, sys::getpid(), code);
    });
    let tid = match spawned {
        Ok(tid) => tid,
        Err(e) => {
            println!("run: could not start '{}': {:?} (limit {} tasks)", name, e, MAX_TASKS);
            return;
        }
    };
    if background {
        println!("[started {} as pid {} in the background]", name, tid);
        return;
    }
    while scheduler::is_alive(tid) {
        if console::read_byte() == Some(CTRL_C) {
            println!("^C");
            scheduler::request_cancel(tid);
        }
        scheduler::sleep_ticks(KEY_POLL_TICKS);
    }
}

fn ps() {
    println!("  PID NAME       STATE       PRIO LEVEL  CPU_TICKS  DISPATCHES");
    for t in scheduler::snapshot() {
        println!(
            "  {:>3} {:<10} {:<11} {:>4} {:>5} {:>10} {:>11}",
            t.tid, t.name, t.state.as_str(), t.prio, t.level, t.cpu_ticks, t.dispatches
        );
    }
}

fn sched() {
    let Some((policy, quantum, preemptive, st, ready)) = scheduler::run_info() else { return };
    let busy = st.ticks.saturating_sub(st.idle_ticks);
    println!("  policy        {} (quantum {} ticks, {})", policy, quantum, if preemptive { "preemptive" } else { "cooperative" });
    println!("  timer ticks   {} ({} idle, CPU busy {}%)", st.ticks, st.idle_ticks, busy * 100 / st.ticks.max(1));
    println!("  dispatches    {}  preemptions {}  yields {}", st.dispatches, st.preemptions, st.yields);
    println!("  blocks        {}  wakeups {}  ready queue {}", st.blocks, st.wakeups, ready);
    println!("  restart with another policy: scripts/shell.sh policy=rr|prio|aging|mlfq|fcfs|sjf|srtf|hrrn quantum=N");
}

fn mem() {
    let h = memory::stats();
    let (ks, ke) = memory::kernel_image();
    println!("  kernel image  {:#x}..{:#x} ({} KiB)", ks, ke, (ke - ks) / 1024);
    println!("  heap          {} KiB first-fit free list", h.capacity / 1024);
    println!("  in use        {} B (peak {} B)", h.bytes_in_use, h.peak_bytes);
    println!("  allocs/frees  {} / {}  (failed {}, rejected frees {})", h.allocs, h.frees, h.failed, h.rejected_frees);
    println!(
        "  free blocks   {}  largest {} B  fragmentation {}.{:02}%",
        h.free_blocks, h.largest_free, h.fragmentation_bp() / 100, h.fragmentation_bp() % 100
    );
}

fn top() {
    loop {
        print!("\x1b[2J\x1b[H");
        println!("Micro-OS top - up {} ms - press any key to quit", sys::uptime_ms());
        sched();
        println!();
        ps();
        if !sys::sleep_ms(1000) || console::read_byte().is_some() {
            return;
        }
    }
}

fn kill(args: &[&str]) {
    match args.first().and_then(|a| a.parse::<usize>().ok()) {
        Some(tid) if tid == sys::getpid() => println!("kill: use 'exit' to stop the shell"),
        Some(tid) if scheduler::request_cancel(tid) => println!("asked pid {} to stop", tid),
        Some(tid) => println!("kill: no task {}", tid),
        None => println!("usage: kill PID"),
    }
}

fn set_trace(args: &[&str]) {
    match args.first() {
        Some(&"on") => {
            console::set_trace(true);
        }
        Some(&"off") => {
            console::set_trace(false);
        }
        _ => println!("usage: trace on|off (currently {})", if console::trace_enabled() { "on" } else { "off" }),
    }
}

fn set_log(args: &[&str]) {
    match args.first().and_then(|a| Level::parse(a)) {
        Some(level) => console::set_level(level),
        None => println!("usage: log error|warn|info|debug (currently {:?})", console::level()),
    }
}

