//! TC4 — stress: many tasks mixing locking, heap traffic, sleeping and
//! yielding, followed by a heap-leak check.

use alloc::{sync::Arc, vec::Vec};
use core::sync::atomic::{AtomicU64, Ordering::Relaxed};

use microos_core::rng::XorShift64;

use super::{print_report, Options, Suite};
use crate::memory;
use crate::scheduler::{self, workload::cpu_burst, Config, SpawnOpts};
use crate::sync::Mutex;

const WORKERS: usize = 48;
const ROUNDS: u64 = 10;

struct Shared {
    counter: Mutex<u64>,
    checksum: AtomicU64,
}

/// Size and fill byte of worker `i`'s allocation in `round` (deterministic).
fn allocation(rng: &mut XorShift64, i: usize, round: u64) -> (usize, u8) {
    (rng.range(16, 4096) as usize, (round as u8) ^ (i as u8))
}

pub fn tc4_stress(s: &mut Suite, o: &Options) {
    let heap_before = memory::stats().bytes_in_use;
    let shared = Arc::new(Shared { counter: Mutex::new("stress", 0), checksum: AtomicU64::new(0) });

    let mut expected_checksum = 0u64;
    for i in 0..WORKERS {
        let mut rng = XorShift64::new(i as u64 + 1);
        for round in 0..ROUNDS {
            let (size, fill) = allocation(&mut rng, i, round);
            expected_checksum += size as u64 * fill as u64;
        }
    }

    scheduler::begin(Config { label: "tc4".into(), policy: o.policy, quantum: o.quantum, preemptive: true, ..Config::default() });
    for i in 0..WORKERS {
        let sh = shared.clone();
        scheduler::spawn("W", SpawnOpts { prio: (i % 8) as u8, delay_ticks: (i % 4) as u64, ..SpawnOpts::default() }, move || {
            let mut rng = XorShift64::new(i as u64 + 1);
            for round in 0..ROUNDS {
                *sh.counter.lock() += 1;
                let (size, fill) = allocation(&mut rng, i, round);
                let mut v: Vec<u8> = Vec::with_capacity(size);
                v.resize(size, fill);
                sh.checksum.fetch_add(v.iter().map(|&b| b as u64).sum(), Relaxed);
                drop(v);
                match round % 3 {
                    0 => scheduler::sleep_ticks(1),
                    1 => cpu_burst(1),
                    _ => scheduler::yield_now(),
                }
            }
        })
        .expect("spawn failed");
    }
    let r = scheduler::run();
    print_report(&r);

    let lock = shared.counter.stats();
    let max_stack = r.tasks.iter().map(|t| t.stack_used).max().unwrap_or(0);
    check!(s, "TC4.complete", r.tasks.len() == WORKERS && !r.deadlock, "{} of {} workers finished", r.tasks.len(), WORKERS);
    let shared = Arc::try_unwrap(shared).ok().expect("workers still hold the shared state");
    let counter = shared.counter.into_inner();
    check!(s, "TC4.mutex_counter", counter == WORKERS as u64 * ROUNDS, "counter={} expected={}", counter, WORKERS as u64 * ROUNDS);
    let checksum = shared.checksum.load(Relaxed);
    check!(s, "TC4.heap_data_integrity", checksum == expected_checksum, "checksum={} expected={}", checksum, expected_checksum);
    kinfo!(
        "TC4: mutex acquisitions={} contended={} max_waiters={} max_wait={}us; peak task stack {} of {} bytes",
        lock.acquisitions, lock.contended, lock.max_waiters, lock.max_wait_us, max_stack, crate::task::STACK_SIZE
    );
    drop(r);
    let heap_after = memory::stats().bytes_in_use;
    check!(s, "TC4.no_heap_leak", heap_after == heap_before, "heap in use before={} after={} bytes", heap_before, heap_after);
}

kernel/src/scenarios/sync_tests.rs.text:
//! Synchronization scenarios: a reproducible race and its fixes, and a
//! bounded-buffer producer/consumer built from semaphores and a mutex.

use alloc::{collections::VecDeque, format, sync::Arc};
use core::sync::atomic::{AtomicU32, AtomicU64, AtomicUsize, Ordering::Relaxed};

use microos_core::sched::PolicyKind;

use super::{print_report, Options, Suite};
use crate::scheduler::{self, workload::spin, Config, SpawnOpts};
use crate::sync::{Mutex, Semaphore, SpinLock};

const WORKERS: u64 = 4;
const INCREMENTS: u64 = 1000;
/// Work done between reading and writing the counter: the race window.
const WINDOW: u32 = 300;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Variant {
    Unsync,
    Spin,
    SpinYield,
    Mutex,
}

impl Variant {
    fn name(self) -> &'static str {
        match self {
            Variant::Unsync => "unsync",
            Variant::Spin => "spin",
            Variant::SpinYield => "spin_yield",
            Variant::Mutex => "mutex",
        }
    }
}

struct Counter {
    racy: AtomicU64,
    spin: SpinLock<u64>,
    mutex: Mutex<u64>,
}

/// Shared counter incremented by 4 preemptible tasks, four ways:
/// unsynchronized (atomic load + store, but not an atomic read-modify-write),
/// busy-wait spinlock, spin-then-yield, and the blocking mutex.
pub fn race(s: &mut Suite, _o: &Options) {
    let expected = WORKERS * INCREMENTS;
    for v in [Variant::Unsync, Variant::Spin, Variant::SpinYield, Variant::Mutex] {
        let c = Arc::new(Counter { racy: AtomicU64::new(0), spin: SpinLock::new(0), mutex: Mutex::new("race", 0) });
        scheduler::begin(Config { label: format!("race_{}", v.name()), policy: PolicyKind::RoundRobin, quantum: 2, preemptive: true, ..Config::default() });
        for _ in 0..WORKERS {
            let c = c.clone();
            scheduler::spawn("INC", SpawnOpts::default(), move || {
                for _ in 0..INCREMENTS {
                    match v {
                        Variant::Unsync => {
                            let x = c.racy.load(Relaxed);
                            spin(WINDOW);
                            c.racy.store(x + 1, Relaxed);
                        }
                        Variant::Spin => {
                            let mut g = c.spin.lock();
                            let x = *g;
                            spin(WINDOW);
                            *g = x + 1;
                        }
                        Variant::SpinYield => {
                            let mut g = c.spin.lock_with(scheduler::yield_now);
                            let x = *g;
                            spin(WINDOW);
                            *g = x + 1;
                        }
                        Variant::Mutex => {
                            let mut g = c.mutex.lock();
                            let x = *g;
                            spin(WINDOW);
                            *g = x + 1;
                        }
                    }
                }
            })
            .expect("spawn failed");
        }
        let r = scheduler::run();
        print_report(&r);

        let c = Arc::try_unwrap(c).ok().expect("workers still hold the counter");
        let spin_stats = c.spin.stats();
        let mstats = c.mutex.stats();
        let result = match v {
            Variant::Unsync => c.racy.load(Relaxed),
            Variant::Spin | Variant::SpinYield => *c.spin.lock(),
            Variant::Mutex => c.mutex.into_inner(),
        };
        let (contended, spins, wait_us) = match v {
            Variant::Mutex => (mstats.contended, 0, mstats.total_wait_us),
            _ => (spin_stats.contended, spin_stats.spins, 0),
        };
        ktrace!(
            "LOCK",
            "variant={} result={} expected={} lost={} elapsed_us={} contended={} spins={} wait_us={} preemptions={} yields={} blocks={}",
            v.name(), result, expected, expected - result, r.elapsed_us, contended, spins, wait_us,
            r.stats.preemptions, r.stats.yields, r.stats.blocks
        );
        kinfo!(
            "race/{}: result={} of {} elapsed={}us contended={} spins={} mutex_wait={}us",
            v.name(), result, expected, r.elapsed_us, contended, spins, wait_us
        );
        if v == Variant::Unsync {
            check!(s, "RACE.unsync_loses_updates", result < expected, "lost {} of {} increments to preemption", expected - result, expected);
        } else {
            check!(s, "RACE.protected_counter_exact", result == expected, "{}: {} of {}", v.name(), result, expected);
        }
    }
}

const CAPACITY: usize = 4;
const ITEMS_PER_PRODUCER: u64 = 25;

struct BoundedBuffer {
    buf: Mutex<VecDeque<u64>>,
    empty_slots: Semaphore,
    full_slots: Semaphore,
    consumed: AtomicU32,
    sum: AtomicU64,
    max_len: AtomicUsize,
}

pub fn producer_consumer(s: &mut Suite, _o: &Options) {
    let bb = Arc::new(BoundedBuffer {
        buf: Mutex::new("buffer", VecDeque::new()),
        empty_slots: Semaphore::new("empty", CAPACITY),
        full_slots: Semaphore::new("full", 0),
        consumed: AtomicU32::new(0),
        sum: AtomicU64::new(0),
        max_len: AtomicUsize::new(0),
    });
    scheduler::begin(Config { label: "prodcons".into(), policy: PolicyKind::RoundRobin, quantum: 2, preemptive: true, ..Config::default() });
    for p in 1..=2u64 {
        let bb = bb.clone();
        scheduler::spawn("PROD", SpawnOpts::default(), move || {
            for i in 0..ITEMS_PER_PRODUCER {
                bb.empty_slots.wait();
                {
                    let mut b = bb.buf.lock();
                    b.push_back(p * 1000 + i);
                    bb.max_len.fetch_max(b.len(), Relaxed);
                }
                bb.full_slots.signal();
                if i % 5 == 4 {
                    scheduler::sleep_ticks(1);
                }
            }
        })
        .unwrap();
    }
    for _ in 0..2 {
        let bb = bb.clone();
        scheduler::spawn("CONS", SpawnOpts::default(), move || {
            for _ in 0..ITEMS_PER_PRODUCER {
                bb.full_slots.wait();
                let item = bb.buf.lock().pop_front().expect("full_slots promised an item");
                bb.empty_slots.signal();
                bb.sum.fetch_add(item, Relaxed);
                bb.consumed.fetch_add(1, Relaxed);
                spin(3000);
            }
        })
        .unwrap();
    }
    let r = scheduler::run();
    print_report(&r);
    if r.deadlock {
        // Abandoned tasks still own Arc clones, so the buffer cannot be inspected.
        check!(s, "PC.no_deadlock", false, "producer/consumer deadlocked");
        return;
    }

    let expected_sum: u64 = (1..=2u64).flat_map(|p| (0..ITEMS_PER_PRODUCER).map(move |i| p * 1000 + i)).sum();
    let bb = Arc::try_unwrap(bb).ok().expect("tasks still hold the buffer");
    let (empty, full) = (bb.empty_slots.stats(), bb.full_slots.stats());
    let max_len = bb.max_len.load(Relaxed);
    let leftover = bb.buf.into_inner().len();
    ktrace!(
        "PRODCONS",
        "consumed={} sum={} expected_sum={} max_len={} capacity={} producer_blocked={} consumer_blocked={}",
        bb.consumed.load(Relaxed), bb.sum.load(Relaxed), expected_sum, max_len, CAPACITY, empty.blocked, full.blocked
    );
    check!(s, "PC.all_items_consumed", bb.consumed.load(Relaxed) == 50 && leftover == 0, "consumed {} of 50, {} left in buffer", bb.consumed.load(Relaxed), leftover);
    check!(s, "PC.no_lost_or_duplicated_items", bb.sum.load(Relaxed) == expected_sum, "sum={} expected={}", bb.sum.load(Relaxed), expected_sum);
    check!(s, "PC.capacity_respected", max_len <= CAPACITY, "max occupancy {} <= {}", max_len, CAPACITY);
    check!(
        s, "PC.both_sides_blocked", empty.blocked > 0 && full.blocked > 0,
        "producers blocked {} times on a full buffer, consumers {} times on an empty one", empty.blocked, full.blocked
    );
}

kernel/src/scenarios/user_tests.rs.text:
//! System calls from U-mode: the user/kernel boundary (Track D / F).
//!
//! Five programs run in U-mode alongside each other under Round Robin:
//! a well-behaved one, one that executes a privileged instruction, one that
//! passes a bad pointer, one that calls an unknown system call, and a
//! CPU-bound one. The checks confirm that each request crossed the boundary
//! the way it should and that a misbehaving program cannot stop the others.

use core::sync::atomic::Ordering::Relaxed;

use microos_core::sched::PolicyKind;

use super::{print_report, Options, Suite};
use crate::scheduler::{self, Config};
use crate::user;

pub fn syscalls(s: &mut Suite, _o: &Options) {
    let calls0 = user::SYSCALLS.load(Relaxed);
    let kills0 = user::KILLS.load(Relaxed);
    let bytes0 = user::BYTES_WRITTEN.load(Relaxed);

    scheduler::begin(Config {
        label: "syscall".into(),
        policy: PolicyKind::RoundRobin,
        quantum: 4,
        preemptive: true,
        ..Config::default()
    });
    let hello = user::spawn("u_hello", user::prog_hello, 2).unwrap();
    let bad = user::spawn("u_priv", user::prog_privileged, 0).unwrap();
    let ptr = user::spawn("u_badptr", user::prog_bad_pointer, 0).unwrap();
    let unk = user::spawn("u_unknown", user::prog_unknown, 0).unwrap();
    // Long enough to keep the CPU busy while u_hello sleeps: a fully idle
    // machine lets QEMU's icount clock jitter by a microsecond across boots.
    let spin = user::spawn("u_spin", user::prog_spin, 6).unwrap();
    let rep = scheduler::run();
    print_report(&rep);

    let calls = user::SYSCALLS.load(Relaxed) - calls0;
    let kills = user::KILLS.load(Relaxed) - kills0;
    let bytes = user::BYTES_WRITTEN.load(Relaxed) - bytes0;
    let task = |tid| rep.tasks.iter().find(|t| t.tid == tid);

    check!(
        s, "SYS.roundtrip", user::exit_code(hello) == Some(0) && calls >= 10 && bytes > 0,
        "u_hello made its calls and exited 0 ({} ecalls in total, {} bytes written via write)", calls, bytes
    );
    check!(
        s, "SYS.privileged_killed", user::exit_code(bad) == Some(user::KILLED) && kills == 1,
        "csrr sstatus in U-mode raised an illegal-instruction trap; the kernel killed only that task (exit {:?})",
        user::exit_code(bad)
    );
    check!(
        s, "SYS.bad_pointer", user::exit_code(ptr) == Some(user::EFAULT),
        "write(0x10, 5) returned {:?} (expected -EFAULT = {})", user::exit_code(ptr), user::EFAULT
    );
    check!(
        s, "SYS.unknown_call", user::exit_code(unk) == Some(user::ENOSYS),
        "syscall 4242 returned {:?} (expected -ENOSYS = {})", user::exit_code(unk), user::ENOSYS
    );
    let spin_pre = task(spin).map_or(0, |t| t.preemptions);
    check!(
        s, "SYS.user_preempted", user::exit_code(spin) == Some(0) && spin_pre > 0,
        "the CPU-bound U-mode task was preempted {} times by the timer and still finished", spin_pre
    );
    check!(
        s, "SYS.others_survive", rep.tasks.len() == 5 && !rep.deadlock,
        "all 5 user tasks finished although one was killed ({} reported, deadlock={})", rep.tasks.len(), rep.deadlock
    );
}

core/src/args.rs.text:
//! Kernel command line: space-separated `key=value` pairs (e.g. `test=tc2 quantum=4`).

#[derive(Clone, Copy, Debug)]
pub struct BootArgs<'a> {
    raw: &'a str,
}

impl<'a> BootArgs<'a> {
    pub const fn new(raw: &'a str) -> Self {
        Self { raw }
    }

    pub fn raw(&self) -> &'a str {
        self.raw
    }

    /// Value of `key`. A bare `key` yields `""`. When a key is repeated the
    /// last occurrence wins, so appended arguments override defaults.
    pub fn get(&self, key: &str) -> Option<&'a str> {
        self.raw
            .split_whitespace()
            .rev()
            .find_map(|kv| match kv.split_once('=') {
                Some((k, v)) if k == key => Some(v),
                None if kv == key => Some(""),
                _ => None,
            })
    }

    pub fn get_u64(&self, key: &str) -> Option<u64> {
        self.get(key)?.parse().ok()
    }

    pub fn flag(&self, key: &str, default: bool) -> bool {
        match self.get(key) {
            Some("" | "1" | "on" | "true" | "yes") => true,
            Some("0" | "off" | "false" | "no") => false,
            _ => default,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_pairs_flags_and_overrides() {
        let a = BootArgs::new("test=tc2 quantum=4 verbose quantum=8 preempt=0");
        assert_eq!(a.get("test"), Some("tc2"));
        assert_eq!(a.get_u64("quantum"), Some(8));
        assert!(a.flag("verbose", false));
        assert!(!a.flag("preempt", true));
        assert!(a.flag("missing", true));
        assert_eq!(a.get("missing"), None);
        assert_eq!(a.get_u64("test"), None);
    }

    #[test]
    fn empty_command_line() {
        let a = BootArgs::new("");
        assert_eq!(a.get("test"), None);
    }
}

core/src/fdt.rs.text:
//! Minimal flattened-device-tree (DTB) reader.
//!
//! The firmware passes the DTB address in `a1`. We only need one property,
//! `/chosen/bootargs` (QEMU fills it from `-append`), so this walks the
//! structure block token by token instead of building a tree.

const MAGIC: u32 = 0xd00d_feed;
const HEADER_LEN: usize = 40;
const TOK_BEGIN_NODE: u32 = 1;
const TOK_END_NODE: u32 = 2;
const TOK_PROP: u32 = 3;
const TOK_NOP: u32 = 4;
const TOK_END: u32 = 9;

fn be32(b: &[u8], off: usize) -> Option<u32> {
    let s = b.get(off..off.checked_add(4)?)?;
    Some(u32::from_be_bytes([s[0], s[1], s[2], s[3]]))
}

fn align4(x: usize) -> usize {
    (x + 3) & !3
}

fn cstr(b: &[u8], off: usize) -> Option<&str> {
    let rest = b.get(off..)?;
    let len = rest.iter().position(|&c| c == 0)?;
    core::str::from_utf8(&rest[..len]).ok()
}

/// Bytes needed to read a DTB header.
pub const fn header_len() -> usize {
    HEADER_LEN
}

/// Total blob size declared in a DTB header, or `None` if the magic is wrong.
pub fn total_size(header: &[u8]) -> Option<usize> {
    if be32(header, 0)? != MAGIC {
        return None;
    }
    Some(be32(header, 4)? as usize)
}

/// Return the `bootargs` property of the `/chosen` node, if present.
/// Every offset is bounds-checked, so a malformed blob yields `None`.
pub fn find_bootargs(blob: &[u8]) -> Option<&str> {
    if be32(blob, 0)? != MAGIC {
        return None;
    }
    let mut off = be32(blob, 8)? as usize;
    let strings = be32(blob, 12)? as usize;
    let mut depth = 0usize;
    let mut chosen_depth: Option<usize> = None;
    loop {
        let tok = be32(blob, off)?;
        off += 4;
        match tok {
            TOK_BEGIN_NODE => {
                let name = cstr(blob, off)?;
                off = align4(off + name.len() + 1);
                depth += 1;
                // depth 1 is the root node; /chosen is one of its children.
                if depth == 2 && (name == "chosen" || name.starts_with("chosen@")) {
                    chosen_depth = Some(depth);
                }
            }
            TOK_END_NODE => {
                if chosen_depth == Some(depth) {
                    chosen_depth = None;
                }
                depth = depth.checked_sub(1)?;
            }
            TOK_PROP => {
                let len = be32(blob, off)? as usize;
                let name_off = be32(blob, off + 4)? as usize;
                off += 8;
                let value = blob.get(off..off.checked_add(len)?)?;
                off = align4(off + len);
                if chosen_depth == Some(depth) && cstr(blob, strings + name_off)? == "bootargs" {
                    let text = value.split(|&c| c == 0).next()?;
                    return core::str::from_utf8(text).ok();
                }
            }
            TOK_NOP => {}
            TOK_END => return None,
            _ => return None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tok(v: &mut Vec<u8>, t: u32) {
        v.extend_from_slice(&t.to_be_bytes());
    }
    fn pad(v: &mut Vec<u8>) {
        while v.len() % 4 != 0 {
            v.push(0);
        }
    }
    fn node(v: &mut Vec<u8>, name: &str) {
        tok(v, TOK_BEGIN_NODE);
        v.extend_from_slice(name.as_bytes());
        v.push(0);
        pad(v);
    }
    fn prop(v: &mut Vec<u8>, name_off: u32, val: &[u8]) {
        tok(v, TOK_PROP);
        tok(v, val.len() as u32);
        tok(v, name_off);
        v.extend_from_slice(val);
        pad(v);
    }

    /// Build a tiny DTB: a decoy `bootargs` in /cpus, the real one in /chosen.
    fn build(bootargs: Option<&str>) -> Vec<u8> {
        let strings = b"model\0bootargs\0"; // "model" at 0, "bootargs" at 6
        let mut st = Vec::new();
        node(&mut st, "");
        prop(&mut st, 0, b"qemu\0");
        node(&mut st, "cpus");
        prop(&mut st, 6, b"decoy\0");
        tok(&mut st, TOK_END_NODE);
        node(&mut st, "chosen");
        tok(&mut st, TOK_NOP);
        if let Some(a) = bootargs {
            let mut val = a.as_bytes().to_vec();
            val.push(0);
            prop(&mut st, 6, &val);
        }
        tok(&mut st, TOK_END_NODE);
        tok(&mut st, TOK_END_NODE);
        tok(&mut st, TOK_END);

        let off_struct = HEADER_LEN as u32;
        let off_strings = off_struct + st.len() as u32;
        let total = off_strings + strings.len() as u32;
        let mut blob = Vec::new();
        for f in [MAGIC, total, off_struct, off_strings, 0, 17, 16, 0, strings.len() as u32, st.len() as u32] {
            tok(&mut blob, f);
        }
        blob.extend_from_slice(&st);
        blob.extend_from_slice(strings);
        blob
    }

    #[test]
    fn finds_chosen_bootargs_and_ignores_other_nodes() {
        let blob = build(Some("test=tc1 quantum=2"));
        assert_eq!(total_size(&blob), Some(blob.len()));
        assert_eq!(find_bootargs(&blob), Some("test=tc1 quantum=2"));
    }

    #[test]
    fn missing_property_and_bad_blobs() {
        assert_eq!(find_bootargs(&build(None)), None);
        let mut bad = build(Some("x=1"));
        bad[0] = 0;
        assert_eq!(total_size(&bad), None);
        assert_eq!(find_bootargs(&bad), None);
        let blob = build(Some("x=1"));
        assert_eq!(find_bootargs(&blob[..60]), None); // truncated: no panic
    }
}

