pub mod spin;

core/src/research.rs.text:
//! Workloads and metrics of the R3 study ("Fairness vs Throughput in CPU
//! Scheduling"), reproduced so the kernel can run the same experiment on
//! real scheduling instead of a simulator.
//!
//! * Burst times: **uniform** U(2, 30) ms, or **bimodal** 75 % U(1, 6) ms
//!   + 25 % U(20, 80) ms (integer milliseconds = timer ticks).
//! * Arrivals: a Poisson process with rate lambda = rho / mean burst. The
//!   kernel's clock is quantised to 1 ms ticks, so arrivals are generated
//!   per tick with probability lambda (a Bernoulli process, the discrete-time
//!   form of Poisson arrivals). At lambda <= 0.073 per ms the chance of two
//!   arrivals in the same millisecond, which this cannot produce, is < 0.3 %.
//! * Fairness: Jain's index J = (sum x)^2 / (n * sum x^2), computed in
//!   integer basis points (10000 = perfectly fair).

use alloc::vec::Vec;

use crate::rng::XorShift64;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Dist {
    Uniform,
    Bimodal,
}

impl Dist {
    pub fn name(self) -> &'static str {
        match self {
            Dist::Uniform => "uniform",
            Dist::Bimodal => "bimodal",
        }
    }

    /// Mean burst in thousandths of a tick: U{2..30} -> 16.0;
    /// 0.75 * U{1..6} + 0.25 * U{20..80} -> 0.75 * 3.5 + 0.25 * 50 = 15.125.
    pub fn mean_milli(self) -> u64 {
        match self {
            Dist::Uniform => 16_000,
            Dist::Bimodal => 15_125,
        }
    }

    pub fn burst(self, rng: &mut XorShift64) -> u32 {
        match self {
            Dist::Uniform => rng.range(2, 31) as u32,
            Dist::Bimodal if rng.range(0, 100) < 75 => rng.range(1, 7) as u32,
            Dist::Bimodal => rng.range(20, 81) as u32,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Job {
    /// Arrival time in ticks after the start of the run.
    pub arrival: u64,
    /// CPU burst in ticks.
    pub burst: u32,
}

/// Jobs arriving in `[0, window)` ticks at offered load `load_pct` / 100.
/// The same seed always produces the same list, so every policy is compared
/// on identical input (as in the study).
pub fn generate(dist: Dist, load_pct: u64, window: u64, seed: u64) -> Vec<Job> {
    let mut arrivals = XorShift64::new(seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) ^ 0xA5A5);
    let mut bursts = XorShift64::new(seed.wrapping_add(0x5151_5151));
    // Probability of an arrival in one tick, in parts per million.
    let p_ppm = load_pct * 10_000 * 1000 / dist.mean_milli();
    (0..window)
        .filter(|_| arrivals.range(0, 1_000_000) < p_ppm)
        .map(|t| Job { arrival: t, burst: dist.burst(&mut bursts) })
        .collect()
}

/// Jain's fairness index in basis points, given sums over n allocations.
pub fn jain_bp(n: u64, sum: u64, sum_sq: u128) -> u64 {
    if n == 0 || sum_sq == 0 {
        return 10_000;
    }
    ((sum as u128 * sum as u128 * 10_000) / (n as u128 * sum_sq)) as u64
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn offered_load_matches_rho() {
        for dist in [Dist::Uniform, Dist::Bimodal] {
            for load in [70u64, 90, 110] {
                let window = 200_000;
                let jobs = generate(dist, load, window, 1);
                let work: u64 = jobs.iter().map(|j| j.burst as u64).sum();
                let rho_pct = work * 100 / window;
                assert!(rho_pct.abs_diff(load) <= 3, "{dist:?} load {load}: measured {rho_pct}");
            }
        }
    }

    #[test]
    fn bimodal_mix_is_75_25_and_deterministic() {
        let jobs = generate(Dist::Bimodal, 110, 100_000, 7);
        let short = jobs.iter().filter(|j| j.burst <= 6).count() as f64 / jobs.len() as f64;
        assert!((0.72..0.78).contains(&short), "short fraction {short}");
        assert!(jobs.iter().all(|j| (1..=6).contains(&j.burst) || (20..=80).contains(&j.burst)));
        assert_eq!(jobs, generate(Dist::Bimodal, 110, 100_000, 7));
        assert_ne!(jobs, generate(Dist::Bimodal, 110, 100_000, 8));
    }

    #[test]
    fn jain_index_extremes() {
        // Equal shares -> 1.0
        assert_eq!(jain_bp(4, 40, 4 * 100), 10_000);
        // One task gets everything -> 1/n
        assert_eq!(jain_bp(4, 10, 100), 2_500);
        assert_eq!(jain_bp(0, 0, 0), 10_000);
    }
}

core/src/rng.rs.text:
//! Deterministic helpers for reproducible experiments.

/// xorshift64 PRNG: tiny, fast and fully deterministic for a given seed,
/// so every workload in the kernel is repeatable run-to-run.
#[derive(Clone, Debug)]
pub struct XorShift64(u64);

impl XorShift64 {
    pub const fn new(seed: u64) -> Self {
        Self(if seed == 0 { 0x9E37_79B9_7F4A_7C15 } else { seed })
    }

    pub fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    /// Uniform-ish value in `lo..hi` (`hi` exclusive, requires `hi > lo`).
    pub fn range(&mut self, lo: u64, hi: u64) -> u64 {
        lo + self.next_u64() % (hi - lo)
    }

    /// True with probability `percent`/100.
    pub fn chance(&mut self, percent: u64) -> bool {
        self.next_u64() % 100 < percent
    }
}

/// FNV-1a hash, used to fingerprint scheduler traces for repeatability checks.
#[derive(Clone, Copy, Debug)]
pub struct Fnv1a(u64);

impl Fnv1a {
    pub const fn new() -> Self {
        Self(0xcbf2_9ce4_8422_2325)
    }

    pub fn write_u64(&mut self, v: u64) {
        for b in v.to_le_bytes() {
            self.0 ^= b as u64;
            self.0 = self.0.wrapping_mul(0x0100_0000_01b3);
        }
    }

    pub fn finish(&self) -> u64 {
        self.0
    }
}

impl Default for Fnv1a {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rng_is_deterministic_and_in_range() {
        let (mut a, mut b) = (XorShift64::new(42), XorShift64::new(42));
        for _ in 0..1000 {
            let x = a.range(10, 20);
            assert_eq!(x, b.range(10, 20));
            assert!((10..20).contains(&x));
        }
    }

    #[test]
    fn fnv_distinguishes_order() {
        let mut a = Fnv1a::new();
        let mut b = Fnv1a::new();
        a.write_u64(1);
        a.write_u64(2);
        b.write_u64(2);
        b.write_u64(1);
        assert_ne!(a.finish(), b.finish());
    }
}

core/src/spin.rs.text:
//! Test-and-test-and-set spinlock with contention counters.
//!
//! What a waiter does while the lock is held is chosen by the caller through
//! `lock_with(relax)`: pure busy-waiting (`spin_loop`) or giving the CPU away
//! (the kernel passes `yield_now`). On a uniprocessor that choice decides
//! whether a waiter burns its whole time slice while the holder is preempted.

use core::cell::UnsafeCell;
use core::ops::{Deref, DerefMut};
use core::sync::atomic::{AtomicBool, AtomicU64, Ordering};

pub struct SpinLock<T> {
    locked: AtomicBool,
    acquisitions: AtomicU64,
    contended: AtomicU64,
    spins: AtomicU64,
    data: UnsafeCell<T>,
}

// SAFETY: `data` is only reachable through a `SpinGuard`, and a guard exists
// only while `locked` is true. Acquire/Release on `locked` orders the
// accesses of successive holders.
unsafe impl<T: Send> Sync for SpinLock<T> {}
unsafe impl<T: Send> Send for SpinLock<T> {}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SpinStats {
    pub acquisitions: u64,
    /// Acquisitions that found the lock already held.
    pub contended: u64,
    /// Total `relax()` calls made while waiting.
    pub spins: u64,
}

impl<T> SpinLock<T> {
    pub const fn new(value: T) -> Self {
        Self {
            locked: AtomicBool::new(false),
            acquisitions: AtomicU64::new(0),
            contended: AtomicU64::new(0),
            spins: AtomicU64::new(0),
            data: UnsafeCell::new(value),
        }
    }

    pub fn try_lock(&self) -> Option<SpinGuard<'_, T>> {
        self.locked
            .compare_exchange(false, true, Ordering::Acquire, Ordering::Relaxed)
            .ok()
            .map(|_| {
                self.acquisitions.fetch_add(1, Ordering::Relaxed);
                SpinGuard { lock: self }
            })
    }

    /// Busy-wait until the lock is free.
    pub fn lock(&self) -> SpinGuard<'_, T> {
        self.lock_with(core::hint::spin_loop)
    }

    /// Wait for the lock, calling `relax` on every failed poll.
    pub fn lock_with(&self, mut relax: impl FnMut()) -> SpinGuard<'_, T> {
        let mut spins = 0u64;
        while self
            .locked
            .compare_exchange_weak(false, true, Ordering::Acquire, Ordering::Relaxed)
            .is_err()
        {
            // Spin on a plain load so waiters do not hammer the line with writes.
            while self.locked.load(Ordering::Relaxed) {
                relax();
                spins += 1;
            }
        }
        self.acquisitions.fetch_add(1, Ordering::Relaxed);
        if spins > 0 {
            self.contended.fetch_add(1, Ordering::Relaxed);
            self.spins.fetch_add(spins, Ordering::Relaxed);
        }
        SpinGuard { lock: self }
    }

    pub fn is_locked(&self) -> bool {
        self.locked.load(Ordering::Relaxed)
    }

    pub fn stats(&self) -> SpinStats {
        SpinStats {
            acquisitions: self.acquisitions.load(Ordering::Relaxed),
            contended: self.contended.load(Ordering::Relaxed),
            spins: self.spins.load(Ordering::Relaxed),
        }
    }
}

pub struct SpinGuard<'a, T> {
    lock: &'a SpinLock<T>,
}

impl<T> Deref for SpinGuard<'_, T> {
    type Target = T;
    fn deref(&self) -> &T {
        // SAFETY: holding the guard means we own the lock.
        unsafe { &*self.lock.data.get() }
    }
}

impl<T> DerefMut for SpinGuard<'_, T> {
    fn deref_mut(&mut self) -> &mut T {
        // SAFETY: holding the guard means we own the lock exclusively.
        unsafe { &mut *self.lock.data.get() }
    }
}

impl<T> Drop for SpinGuard<'_, T> {
    fn drop(&mut self) {
        self.lock.locked.store(false, Ordering::Release);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;

    #[test]
    fn mutual_exclusion_across_threads() {
        let lock = Arc::new(SpinLock::new(0u64));
        let handles: Vec<_> = (0..4)
            .map(|_| {
                let lock = lock.clone();
                std::thread::spawn(move || {
                    for _ in 0..20_000 {
                        *lock.lock() += 1;
                    }
                })
            })
            .collect();
        for h in handles {
            h.join().unwrap();
        }
        assert_eq!(*lock.lock(), 80_000);
        assert_eq!(lock.stats().acquisitions, 80_001);
    }

    #[test]
    fn try_lock_fails_while_held_and_relax_is_called() {
        let lock = SpinLock::new(());
        let g = lock.try_lock().unwrap();
        assert!(lock.try_lock().is_none());
        drop(g);
        assert!(!lock.is_locked());

        // A relax callback that releases the lock proves waiters call it.
        let lock = SpinLock::new(1);
        let g = lock.lock();
        let mut held = Some(g);
        let g2 = lock.lock_with(|| {
            held.take();
        });
        assert_eq!(*g2, 1);
        assert_eq!(lock.stats().contended, 1);
    }
}

core/src/sched/classic.rs.text:
//! The four non-Round-Robin policies compared in the R3 research study
//! ("Fairness vs Throughput in CPU Scheduling"):
//!
//! | policy | picks                                   | preemptive |
//! |--------|-----------------------------------------|------------|
//! | FCFS   | earliest arrival                        | no         |
//! | SJF    | shortest expected burst                 | no         |
//! | SRTF   | shortest expected *remaining* time      | yes, when a shorter job becomes ready |
//! | HRRN   | highest response ratio (w + s) / s      | no         |
//!
//! Non-preemptive policies give the dispatched task a quantum of
//! `RUN_TO_COMPLETION`, so the timer never takes the CPU away; the task
//! keeps it until it blocks or exits, exactly like the study's simulator.
//! Burst lengths come from `SchedInfo::burst_est` (see there).

use alloc::collections::VecDeque;
use alloc::vec::Vec;

use super::{Pick, Policy, Reason, SchedInfo, Tid};

/// Quantum meaning "never preempt on a timer tick".
pub const RUN_TO_COMPLETION: u32 = u32::MAX;

/// A waiting task with the value it is ordered by.
struct Entry {
    tid: Tid,
    key: u32,
    since: u64,
    seq: u64,
}

/// Remove the entry with the smallest (key, seq): FIFO among equal keys.
fn take_min(ready: &mut Vec<Entry>) -> Option<Entry> {
    let i = ready.iter().enumerate().min_by_key(|(_, e)| (e.key, e.seq)).map(|(i, _)| i)?;
    Some(ready.swap_remove(i))
}

// ------------------------------------------------------------------ FCFS

pub struct Fcfs {
    ready: VecDeque<Tid>,
}

impl Fcfs {
    pub fn new() -> Self {
        Self { ready: VecDeque::new() }
    }
}

impl Default for Fcfs {
    fn default() -> Self {
        Self::new()
    }
}

impl Policy for Fcfs {
    fn name(&self) -> &'static str {
        "FCFS"
    }
    fn enqueue(&mut self, info: &mut SchedInfo, _reason: Reason, _now: u64) {
        self.ready.push_back(info.tid);
    }
    fn pick_next(&mut self, _now: u64) -> Option<Pick> {
        self.ready.pop_front().map(|tid| Pick { tid, level: 0 })
    }
    fn quantum(&self, _info: &SchedInfo) -> u32 {
        RUN_TO_COMPLETION
    }
    fn ready_len(&self) -> usize {
        self.ready.len()
    }
}

// ------------------------------------------------------------------ SJF

/// Non-preemptive Shortest Job First.
pub struct Sjf {
    ready: Vec<Entry>,
    seq: u64,
}

impl Sjf {
    pub fn new() -> Self {
        Self { ready: Vec::new(), seq: 0 }
    }
}

impl Default for Sjf {
    fn default() -> Self {
        Self::new()
    }
}

impl Policy for Sjf {
    fn name(&self) -> &'static str {
        "SJF"
    }
    fn enqueue(&mut self, info: &mut SchedInfo, _reason: Reason, now: u64) {
        self.ready.push(Entry { tid: info.tid, key: info.remaining(), since: now, seq: self.seq });
        self.seq += 1;
    }
    fn pick_next(&mut self, _now: u64) -> Option<Pick> {
        take_min(&mut self.ready).map(|e| Pick { tid: e.tid, level: 0 })
    }
    fn quantum(&self, _info: &SchedInfo) -> u32 {
        RUN_TO_COMPLETION
    }
    fn ready_len(&self) -> usize {
        self.ready.len()
    }
}

// ------------------------------------------------------------------ SRTF

/// Shortest Remaining Time First: SJF that preempts when a task with less
/// remaining work becomes ready (checked on every timer tick).
pub struct Srtf {
    ready: Vec<Entry>,
    seq: u64,
}

impl Srtf {
    pub fn new() -> Self {
        Self { ready: Vec::new(), seq: 0 }
    }
}

impl Default for Srtf {
    fn default() -> Self {
        Self::new()
    }
}

impl Policy for Srtf {
    fn name(&self) -> &'static str {
        "SRTF"
    }
    fn enqueue(&mut self, info: &mut SchedInfo, _reason: Reason, now: u64) {
        self.ready.push(Entry { tid: info.tid, key: info.remaining(), since: now, seq: self.seq });
        self.seq += 1;
    }
    fn pick_next(&mut self, _now: u64) -> Option<Pick> {
        take_min(&mut self.ready).map(|e| Pick { tid: e.tid, level: 0 })
    }
    fn quantum(&self, _info: &SchedInfo) -> u32 {
        RUN_TO_COMPLETION
    }
    fn should_preempt(&self, running: &SchedInfo) -> bool {
        let left = running.remaining();
        self.ready.iter().any(|e| e.key < left)
    }
    fn ready_len(&self) -> usize {
        self.ready.len()
    }
}

// ------------------------------------------------------------------ HRRN

/// Highest Response Ratio Next (Stallings): ratio = (waiting + service) / service.
/// The ratio of a waiting task grows, which is a built-in form of aging.
pub struct Hrrn {
    ready: Vec<Entry>,
    seq: u64,
}

impl Hrrn {
    pub fn new() -> Self {
        Self { ready: Vec::new(), seq: 0 }
    }
}

impl Default for Hrrn {
    fn default() -> Self {
        Self::new()
    }
}

impl Policy for Hrrn {
    fn name(&self) -> &'static str {
        "HRRN"
    }
    fn enqueue(&mut self, info: &mut SchedInfo, _reason: Reason, now: u64) {
        self.ready.push(Entry { tid: info.tid, key: info.remaining().max(1), since: now, seq: self.seq });
        self.seq += 1;
    }
    fn pick_next(&mut self, now: u64) -> Option<Pick> {
        // Compare (w_a + s_a) / s_a against (w_b + s_b) / s_b by cross-multiplying,
        // so no floating point is needed.
        let mut best: Option<usize> = None;
        for (i, e) in self.ready.iter().enumerate() {
            let better = match best {
                None => true,
                Some(b) => {
                    let o = &self.ready[b];
                    let lhs = (now - e.since + e.key as u64) as u128 * o.key as u128;
                    let rhs = (now - o.since + o.key as u64) as u128 * e.key as u128;
                    lhs > rhs || (lhs == rhs && e.seq < o.seq)
                }
            };
            if better {
                best = Some(i);
            }
        }
        let e = self.ready.swap_remove(best?);
        Some(Pick { tid: e.tid, level: 0 })
    }
    fn quantum(&self, _info: &SchedInfo) -> u32 {
        RUN_TO_COMPLETION
    }
    fn ready_len(&self) -> usize {
        self.ready.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn job(tid: Tid, burst: u32) -> SchedInfo {
        SchedInfo { tid, burst_est: burst, ..SchedInfo::default() }
    }

    fn drain(p: &mut dyn Policy, now: u64) -> Vec<Tid> {
        core::iter::from_fn(|| p.pick_next(now).map(|x| x.tid)).collect()
    }

    #[test]
    fn fcfs_is_arrival_order_and_never_preempts() {
        let mut p = Fcfs::new();
        for (t, b) in [(1, 30), (2, 2), (3, 10)] {
            p.enqueue(&mut job(t, b), Reason::New, 0);
        }
        assert_eq!(p.quantum(&job(9, 1)), RUN_TO_COMPLETION);
        assert!(!p.should_preempt(&job(9, 1000)));
        assert_eq!(drain(&mut p, 0), vec![1, 2, 3]);
    }

    #[test]
    fn sjf_picks_shortest_fifo_on_ties() {
        let mut p = Sjf::new();
        for (t, b) in [(1, 30), (2, 5), (3, 10), (4, 5)] {
            p.enqueue(&mut job(t, b), Reason::New, 0);
        }
        assert_eq!(drain(&mut p, 0), vec![2, 4, 3, 1]);
    }

    #[test]
    fn srtf_preempts_only_for_strictly_shorter_remaining() {
        let mut p = Srtf::new();
        let mut running = job(1, 20);
        running.burst_used = 12; // 8 ticks left
        p.enqueue(&mut job(2, 8), Reason::New, 0);
        assert!(!p.should_preempt(&running), "equal remaining: keep running");
        p.enqueue(&mut job(3, 7), Reason::New, 0);
        assert!(p.should_preempt(&running));
        // A preempted task re-enters with its remaining time as the key.
        p.enqueue(&mut running, Reason::Preempted, 0);
        assert_eq!(drain(&mut p, 0), vec![3, 2, 1]);
    }

    #[test]
    fn hrrn_lets_a_long_waiting_job_overtake_short_ones() {
        let mut p = Hrrn::new();
        p.enqueue(&mut job(1, 50), Reason::New, 0); // waits from t=0
        p.enqueue(&mut job(2, 4), Reason::New, 100); // arrives at t=100
        // t=101: ratios 1 + 101/50 = 3.02 vs 1 + 1/4 = 1.25: the old long job wins.
        assert_eq!(p.pick_next(101).unwrap().tid, 1);
        p.enqueue(&mut job(1, 50), Reason::New, 101);
        // t=102: job 2 has waited 2 ticks (ratio 1.5) vs job 1's 1.02: short job wins.
        assert_eq!(p.pick_next(102).unwrap().tid, 2);
    }
}

core/src/sched/mlfq.rs.text:
//! Multi-Level Feedback Queue (after OSTEP ch. 8).
//!
//! * Rule 1/2: higher queue wins; equal queues run round-robin.
//! * Rule 3: new tasks start in the top queue.
//! * Rule 4: once a task has used its allotment at a level (summed across
//!   yields and blocks, so it cannot game the scheduler by yielding just
//!   before the quantum ends) it moves down one level.
//! * Rule 5: every `boost_period` ticks all tasks return to the top queue.
//!
//! Level `l` has quantum `base << l`, and its allotment equals that quantum.
//! The boost is implemented with an epoch counter so tasks that are running
//! or blocked at boost time are reset lazily the next time we see them.

use alloc::collections::VecDeque;

use super::{Leave, Pick, Policy, PolicyEvent, Reason, SchedInfo, Tid};

pub const MLFQ_LEVELS: usize = 3;
pub const BOOST_PERIOD: u64 = 50;

pub struct Mlfq {
    queues: [VecDeque<Tid>; MLFQ_LEVELS],
    base_quantum: u32,
    boost_period: u64,
    last_boost: u64,
    epoch: u64,
}

impl Mlfq {
    pub fn new(base_quantum: u32, boost_period: u64) -> Self {
        Self {
            queues: [VecDeque::new(), VecDeque::new(), VecDeque::new()],
            base_quantum: base_quantum.max(1),
            boost_period: boost_period.max(1),
            last_boost: 0,
            epoch: 0,
        }
    }

    fn quantum_at(&self, level: u8) -> u32 {
        self.base_quantum << level
    }

    /// Bring `info` up to date with the latest boost. Returns true if it was stale.
    fn sync_epoch(&self, info: &mut SchedInfo) -> bool {
        if info.epoch == self.epoch {
            return false;
        }
        info.epoch = self.epoch;
        info.level = 0;
        info.allot_used = 0;
        true
    }
}

impl Policy for Mlfq {
    fn name(&self) -> &'static str {
        "MLFQ"
    }

    fn enqueue(&mut self, info: &mut SchedInfo, reason: Reason, _now: u64) {
        self.sync_epoch(info);
        if reason == Reason::New {
            info.level = 0;
            info.allot_used = 0;
        }
        let level = (info.level as usize).min(MLFQ_LEVELS - 1);
        self.queues[level].push_back(info.tid);
    }

    fn pick_next(&mut self, _now: u64) -> Option<Pick> {
        self.queues
            .iter_mut()
            .enumerate()
            .find_map(|(l, q)| q.pop_front().map(|tid| Pick { tid, level: l as u8 }))
    }

    fn on_dispatch(&mut self, info: &mut SchedInfo, level: u8) {
        if info.epoch != self.epoch {
            info.epoch = self.epoch;
            info.allot_used = 0;
        }
        info.level = level;
    }

    fn quantum(&self, info: &SchedInfo) -> u32 {
        self.quantum_at(info.level)
    }

    fn on_descheduled(&mut self, info: &mut SchedInfo, ran: u32, why: Leave) -> Option<PolicyEvent> {
        if why == Leave::Exited || self.sync_epoch(info) {
            return None;
        }
        info.allot_used += ran;
        if info.allot_used < self.quantum_at(info.level) {
            return None;
        }
        info.allot_used = 0;
        if (info.level as usize) < MLFQ_LEVELS - 1 {
            let from = info.level;
            info.level += 1;
            return Some(PolicyEvent::Demoted { tid: info.tid, from, to: info.level });
        }
        None
    }

    fn should_preempt(&self, running: &SchedInfo) -> bool {
        let level = (running.level as usize).min(MLFQ_LEVELS);
        self.queues[..level].iter().any(|q| !q.is_empty())
    }

    fn on_tick(&mut self, now: u64) -> Option<PolicyEvent> {
        if now.saturating_sub(self.last_boost) < self.boost_period {
            return None;
        }
        self.last_boost = now;
        self.epoch += 1;
        let mut moved = 0;
        for l in 1..MLFQ_LEVELS {
            while let Some(t) = self.queues[l].pop_front() {
                self.queues[0].push_back(t);
                moved += 1;
            }
        }
        Some(PolicyEvent::Boosted { moved })
    }

    fn ready_len(&self) -> usize {
        self.queues.iter().map(VecDeque::len).sum()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Simulate one dispatch of `info` that runs `ran` ticks and leaves with `why`.
    fn run(p: &mut Mlfq, info: &mut SchedInfo, ran: u32, why: Leave) -> Option<PolicyEvent> {
        let pick = p.pick_next(0).unwrap();
        assert_eq!(pick.tid, info.tid);
        p.on_dispatch(info, pick.level);
        let ev = p.on_descheduled(info, ran, why);
        if why != Leave::Exited {
            p.enqueue(info, if why == Leave::Preempted { Reason::Preempted } else { Reason::Woken }, 0);
        }
        ev
    }

    #[test]
    fn cpu_bound_task_sinks_level_by_level() {
        let mut p = Mlfq::new(2, 1000);
        let mut t = SchedInfo::new(1, 4);
        p.enqueue(&mut t, Reason::New, 0);
        assert_eq!(p.quantum(&t), 2);
        assert_eq!(run(&mut p, &mut t, 2, Leave::Preempted), Some(PolicyEvent::Demoted { tid: 1, from: 0, to: 1 }));
        assert_eq!(p.quantum(&t), 4);
        assert_eq!(run(&mut p, &mut t, 4, Leave::Preempted), Some(PolicyEvent::Demoted { tid: 1, from: 1, to: 2 }));
        assert_eq!(run(&mut p, &mut t, 8, Leave::Preempted), None, "bottom level stays put");
        assert_eq!(t.level, 2);
    }

    #[test]
    fn yielding_early_cannot_game_the_allotment() {
        let mut p = Mlfq::new(4, 1000);
        let mut t = SchedInfo::new(1, 4);
        p.enqueue(&mut t, Reason::New, 0);
        for _ in 0..3 {
            assert_eq!(run(&mut p, &mut t, 1, Leave::Blocked), None);
        }
        assert_eq!(run(&mut p, &mut t, 1, Leave::Blocked), Some(PolicyEvent::Demoted { tid: 1, from: 0, to: 1 }));
    }

    #[test]
    fn higher_queue_preempts_and_boost_resets() {
        let mut p = Mlfq::new(1, 10);
        let mut hog = SchedInfo::new(1, 4);
        p.enqueue(&mut hog, Reason::New, 0);
        run(&mut p, &mut hog, 1, Leave::Preempted);
        run(&mut p, &mut hog, 2, Leave::Preempted);
        assert_eq!(hog.level, 2);
        let mut fresh = SchedInfo::new(2, 4);
        p.enqueue(&mut fresh, Reason::New, 0);
        assert!(p.should_preempt(&hog));
        assert!(!p.should_preempt(&fresh));

        assert_eq!(p.on_tick(5), None);
        assert_eq!(p.on_tick(10), Some(PolicyEvent::Boosted { moved: 1 }));
        // The hog's info is stale; it is reset to level 0 when next seen.
        let picks: Vec<_> = core::iter::from_fn(|| p.pick_next(10)).collect();
        assert!(picks.iter().all(|x| x.level == 0));
        p.on_dispatch(&mut hog, 0);
        assert_eq!((hog.level, hog.allot_used), (0, 0));
    }
}

core/src/sched/mod.rs.text:
//! CPU scheduling policies.
//!
//! A policy owns only the *ready queue*: which runnable task goes next and
//! for how long. The kernel owns tasks, contexts and the timer, and calls
//! into the policy at well-defined points:
//!
//! ```text
//!   task becomes runnable ──► enqueue(info, reason)
//!   CPU is free           ──► pick_next() ──► on_dispatch(info, level) ──► run for quantum(info)
//!   every timer tick      ──► on_tick(); should_preempt(running)?
//!   task leaves the CPU   ──► on_descheduled(info, ticks_ran, why)
//! ```
//!
//! Keeping policies free of hardware details lets them be unit-tested on the
//! host and swapped at boot (`policy=rr|prio|aging|mlfq|fcfs|sjf|srtf|hrrn`).
//!
//! FCFS, SJF, SRTF and HRRN are the policies compared in the R3 research
//! study ("Fairness vs Throughput in CPU Scheduling"); see `classic.rs`.

mod classic;
mod mlfq;
mod priority;
mod rr;

use alloc::boxed::Box;

pub use classic::{Fcfs, Hrrn, Sjf, Srtf, RUN_TO_COMPLETION};
pub use mlfq::{Mlfq, BOOST_PERIOD, MLFQ_LEVELS};
pub use priority::{PriorityPolicy, AGING_INTERVAL, DEFAULT_PRIO, LOWEST_PRIO};
pub use rr::RoundRobin;

pub type Tid = usize;

/// Why a task is being put on the ready queue.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Reason {
    New,
    Preempted,
    Yielded,
    Woken,
}

/// Why a task left the CPU.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Leave {
    Preempted,
    Yielded,
    Blocked,
    Exited,
}

impl Leave {
    pub fn as_str(self) -> &'static str {
        match self {
            Leave::Preempted => "preempt",
            Leave::Yielded => "yield",
            Leave::Blocked => "block",
            Leave::Exited => "exit",
        }
    }
}

/// Per-task scheduling state that lives in the kernel's task control block
/// and is handed to the policy whenever it needs it.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SchedInfo {
    pub tid: Tid,
    /// Static priority, 0 = highest.
    pub base_prio: u8,
    /// Level the task was dispatched at (priority or MLFQ queue).
    pub level: u8,
    /// MLFQ: ticks consumed at the current level (the "allotment").
    pub allot_used: u32,
    /// MLFQ: boost epoch this info was last synchronised with.
    pub epoch: u64,
    /// Expected length of the current CPU burst, in ticks. Either the true
    /// value (an "oracle", as in the R3 simulator) or a prediction made by
    /// exponential averaging of past bursts (what a real OS has to do).
    pub burst_est: u32,
    /// Ticks of CPU consumed in the current burst.
    pub burst_used: u32,
}

impl SchedInfo {
    pub fn new(tid: Tid, base_prio: u8) -> Self {
        Self { tid, base_prio, ..Self::default() }
    }

    /// Expected CPU still needed in the current burst (SRTF's key).
    pub fn remaining(&self) -> u32 {
        self.burst_est.saturating_sub(self.burst_used)
    }

    /// End of a CPU burst in prediction mode: tau' = (actual + tau) / 2,
    /// i.e. exponential averaging with alpha = 1/2 (Silberschatz ch. 5).
    pub fn end_burst_predicted(&mut self) {
        self.burst_est = ((self.burst_used + self.burst_est) / 2).max(1);
        self.burst_used = 0;
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Pick {
    pub tid: Tid,
    pub level: u8,
}

/// Notable policy decisions, reported to the kernel trace.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PolicyEvent {
    Demoted { tid: Tid, from: u8, to: u8 },
    Boosted { moved: usize },
    Aged { count: usize },
}

pub trait Policy: Send {
    fn name(&self) -> &'static str;

    /// Add a runnable task to the ready queue.
    fn enqueue(&mut self, info: &mut SchedInfo, reason: Reason, now: u64);

    /// Remove and return the task that should run next.
    fn pick_next(&mut self, now: u64) -> Option<Pick>;

    /// Called right after `pick_next` with the picked task's info.
    fn on_dispatch(&mut self, info: &mut SchedInfo, level: u8) {
        info.level = level;
    }

    /// Time slice, in timer ticks, for a task being dispatched.
    fn quantum(&self, info: &SchedInfo) -> u32;

    /// Account for a task leaving the CPU after running `ran` ticks.
    fn on_descheduled(&mut self, _info: &mut SchedInfo, _ran: u32, _why: Leave) -> Option<PolicyEvent> {
        None
    }

    /// Should the running task be preempted before its quantum expires?
    fn should_preempt(&self, _running: &SchedInfo) -> bool {
        false
    }

    /// Periodic housekeeping (aging, priority boost).
    fn on_tick(&mut self, _now: u64) -> Option<PolicyEvent> {
        None
    }

    fn ready_len(&self) -> usize;
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PolicyKind {
    RoundRobin,
    Priority,
    PriorityAging,
    Mlfq,
    Fcfs,
    Sjf,
    Srtf,
    Hrrn,
}

impl PolicyKind {
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "rr" | "roundrobin" => Some(Self::RoundRobin),
            "prio" | "priority" => Some(Self::Priority),
            "aging" | "prio-aging" => Some(Self::PriorityAging),
            "mlfq" => Some(Self::Mlfq),
            "fcfs" => Some(Self::Fcfs),
            "sjf" => Some(Self::Sjf),
            "srtf" => Some(Self::Srtf),
            "hrrn" => Some(Self::Hrrn),
            _ => None,
        }
    }

    /// Policies that order the queue by (expected) burst length.
    pub fn needs_bursts(self) -> bool {
        matches!(self, Self::Sjf | Self::Srtf | Self::Hrrn)
    }
}

pub fn build(kind: PolicyKind, quantum: u32) -> Box<dyn Policy> {
    match kind {
        PolicyKind::RoundRobin => Box::new(RoundRobin::new(quantum)),
        PolicyKind::Priority => Box::new(PriorityPolicy::new(quantum, None)),
        PolicyKind::PriorityAging => Box::new(PriorityPolicy::new(quantum, Some(AGING_INTERVAL))),
        PolicyKind::Mlfq => Box::new(Mlfq::new(quantum, BOOST_PERIOD)),
        PolicyKind::Fcfs => Box::new(Fcfs::new()),
        PolicyKind::Sjf => Box::new(Sjf::new()),
        PolicyKind::Srtf => Box::new(Srtf::new()),
        PolicyKind::Hrrn => Box::new(Hrrn::new()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_names() {
        assert_eq!(PolicyKind::parse("mlfq"), Some(PolicyKind::Mlfq));
        assert_eq!(PolicyKind::parse("rr"), Some(PolicyKind::RoundRobin));
        assert_eq!(PolicyKind::parse("fifo"), None);
        assert_eq!(PolicyKind::parse("srtf"), Some(PolicyKind::Srtf));
        assert_eq!(build(PolicyKind::PriorityAging, 4).name(), "PRIO+AGING");
        assert_eq!(build(PolicyKind::Hrrn, 4).name(), "HRRN");
    }

    #[test]
    fn exponential_averaging_tracks_bursts() {
        let mut i = SchedInfo { burst_est: 8, ..SchedInfo::default() };
        for _ in 0..6 {
            i.burst_used = 2; // the task keeps running for 2 ticks per burst
            i.end_burst_predicted();
        }
        assert_eq!(i.burst_est, 2, "estimate converges to the observed burst");
        i.burst_used = 30;
        i.end_burst_predicted();
        assert_eq!(i.burst_est, 16, "one long burst moves the estimate half way");
    }
}

core/src/sched/priority.rs.text:
//! Preemptive static-priority scheduling, optionally with aging.
//!
//! Lower number = higher priority. Equal priorities run round-robin (FIFO by
//! enqueue order). Without aging a steady stream of high-priority work
//! starves low-priority tasks; with aging every `interval` ticks spent
//! waiting raises a task's effective priority by one level, and the raised
//! level is kept for the slice it is dispatched with.

use alloc::vec::Vec;

use super::{Pick, Policy, PolicyEvent, Reason, SchedInfo, Tid};

pub const LOWEST_PRIO: u8 = 7;
pub const DEFAULT_PRIO: u8 = 4;
pub const AGING_INTERVAL: u64 = 10;

struct Entry {
    tid: Tid,
    eff: u8,
    since: u64,
    seq: u64,
}

pub struct PriorityPolicy {
    ready: Vec<Entry>,
    quantum: u32,
    aging: Option<u64>,
    seq: u64,
}

impl PriorityPolicy {
    pub fn new(quantum: u32, aging: Option<u64>) -> Self {
        Self { ready: Vec::new(), quantum: quantum.max(1), aging, seq: 0 }
    }
}

impl Policy for PriorityPolicy {
    fn name(&self) -> &'static str {
        if self.aging.is_some() {
            "PRIO+AGING"
        } else {
            "PRIO"
        }
    }

    fn enqueue(&mut self, info: &mut SchedInfo, _reason: Reason, now: u64) {
        let eff = info.base_prio.min(LOWEST_PRIO);
        self.ready.push(Entry { tid: info.tid, eff, since: now, seq: self.seq });
        self.seq += 1;
    }

    fn pick_next(&mut self, _now: u64) -> Option<Pick> {
        // Linear scan: the ready set is at most MAX_TASKS entries.
        let i = self
            .ready
            .iter()
            .enumerate()
            .min_by_key(|(_, e)| (e.eff, e.seq))
            .map(|(i, _)| i)?;
        let e = self.ready.swap_remove(i);
        Some(Pick { tid: e.tid, level: e.eff })
    }

    fn quantum(&self, _info: &SchedInfo) -> u32 {
        self.quantum
    }

    fn should_preempt(&self, running: &SchedInfo) -> bool {
        self.ready.iter().any(|e| e.eff < running.level)
    }

    fn on_tick(&mut self, now: u64) -> Option<PolicyEvent> {
        let interval = self.aging?;
        let mut count = 0;
        for e in &mut self.ready {
            if e.eff > 0 && now.saturating_sub(e.since) >= interval {
                e.eff -= 1;
                e.since = now;
                count += 1;
            }
        }
        (count > 0).then_some(PolicyEvent::Aged { count })
    }

    fn ready_len(&self) -> usize {
        self.ready.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn info(tid: Tid, prio: u8) -> SchedInfo {
        SchedInfo::new(tid, prio)
    }

    #[test]
    fn highest_priority_first_fifo_within_level() {
        let mut p = PriorityPolicy::new(4, None);
        for (tid, prio) in [(1, 5), (2, 1), (3, 5), (4, 1)] {
            p.enqueue(&mut info(tid, prio), Reason::New, 0);
        }
        let order: Vec<_> = core::iter::from_fn(|| p.pick_next(0).map(|x| x.tid)).collect();
        assert_eq!(order, vec![2, 4, 1, 3]);
    }

    #[test]
    fn preempts_for_higher_priority_only() {
        let mut p = PriorityPolicy::new(4, None);
        let mut running = info(1, 3);
        running.level = 3;
        p.enqueue(&mut info(2, 3), Reason::New, 0);
        assert!(!p.should_preempt(&running));
        p.enqueue(&mut info(3, 2), Reason::Woken, 0);
        assert!(p.should_preempt(&running));
    }

    #[test]
    fn aging_lifts_a_starved_task() {
        let mut p = PriorityPolicy::new(4, Some(10));
        p.enqueue(&mut info(9, 7), Reason::New, 0);
        let mut ev = None;
        for now in 1..=50 {
            ev = p.on_tick(now).or(ev);
        }
        assert_eq!(ev, Some(PolicyEvent::Aged { count: 1 }));
        p.enqueue(&mut info(1, 3), Reason::New, 50);
        let pick = p.pick_next(50).unwrap();
        assert_eq!((pick.tid, pick.level), (9, 2), "aged from 7 to 2 after 50 ticks");
    }

    #[test]
    fn no_aging_without_interval() {
        let mut p = PriorityPolicy::new(4, None);
        p.enqueue(&mut info(9, 7), Reason::New, 0);
        assert_eq!(p.on_tick(1000), None);
        assert_eq!(p.pick_next(1000).unwrap().level, 7);
    }
}

core/src/sched/rr.rs.text:
//! Round Robin: one FIFO ready queue and a fixed time quantum.

use alloc::collections::VecDeque;

use super::{Pick, Policy, Reason, SchedInfo, Tid};

pub struct RoundRobin {
    ready: VecDeque<Tid>,
    quantum: u32,
}

impl RoundRobin {
    pub fn new(quantum: u32) -> Self {
        Self { ready: VecDeque::new(), quantum: quantum.max(1) }
    }
}

impl Policy for RoundRobin {
    fn name(&self) -> &'static str {
        "RR"
    }

    fn enqueue(&mut self, info: &mut SchedInfo, _reason: Reason, _now: u64) {
        self.ready.push_back(info.tid);
    }

    fn pick_next(&mut self, _now: u64) -> Option<Pick> {
        self.ready.pop_front().map(|tid| Pick { tid, level: 0 })
    }

    fn quantum(&self, _info: &SchedInfo) -> u32 {
        self.quantum
    }

    fn ready_len(&self) -> usize {
        self.ready.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fifo_rotation() {
        let mut p = RoundRobin::new(0);
        assert_eq!(p.quantum(&SchedInfo::default()), 1, "quantum is clamped to >= 1");
        let mut infos: Vec<_> = (1..=3).map(|t| SchedInfo::new(t, 4)).collect();
        for i in &mut infos {
            p.enqueue(i, Reason::New, 0);
        }
        let first = p.pick_next(0).unwrap().tid;
        p.enqueue(&mut infos[0], Reason::Preempted, 1);
        let order: Vec<_> = core::iter::from_fn(|| p.pick_next(0).map(|x| x.tid)).collect();
        assert_eq!((first, order), (1, vec![2, 3, 1]));
        assert_eq!(p.ready_len(), 0);
    }
}

core/src/mem/bump.rs.text:
//! Bump allocator: a single "next free" pointer that only moves forward.
//!
//! Allocation is O(1) and branch-light, but individual frees cannot be
//! reused: memory is reclaimed only when *every* allocation has been freed.

use core::alloc::Layout;
use core::ptr::null_mut;

use super::{align_up, AllocStats, FreeError, RegionAllocator};

pub struct BumpAllocator {
    start: usize,
    end: usize,
    next: usize,
    live: usize,
    stats: AllocStats,
}

impl BumpAllocator {
    pub const fn empty() -> Self {
        Self { start: 0, end: 0, next: 0, live: 0, stats: AllocStats::new() }
    }

    /// # Safety
    /// `[start, start + size)` must be valid, writable memory that nothing
    /// else uses for as long as this allocator hands out blocks from it.
    pub unsafe fn init(&mut self, start: usize, size: usize) {
        self.start = start;
        self.end = start + size;
        self.next = start;
        self.live = 0;
        self.stats = AllocStats { capacity: size, ..AllocStats::new() };
    }

    fn update_usage(&mut self) {
        self.stats.bytes_in_use = self.next - self.start;
        self.stats.peak_bytes = self.stats.peak_bytes.max(self.stats.bytes_in_use);
    }
}

impl RegionAllocator for BumpAllocator {
    fn name(&self) -> &'static str {
        "bump"
    }

    fn alloc(&mut self, layout: Layout) -> *mut u8 {
        let start = align_up(self.next, layout.align());
        match start.checked_add(layout.size()) {
            Some(end) if end <= self.end => {
                self.next = end;
                self.live += 1;
                self.stats.allocs += 1;
                self.update_usage();
                start as *mut u8
            }
            _ => {
                self.stats.failed += 1;
                null_mut()
            }
        }
    }

    // Safety: the Allocator::dealloc contract (no use of `ptr` afterwards).
    // Only bounds and the live count are read; memory is never touched.
    unsafe fn dealloc(&mut self, ptr: *mut u8, _layout: Layout) -> Result<(), FreeError> {
        let p = ptr as usize;
        let verdict = if p < self.start || p >= self.next {
            Err(FreeError::OutOfRange)
        } else if self.live == 0 {
            Err(FreeError::NotAllocated)
        } else {
            Ok(())
        };
        if verdict.is_err() {
            self.stats.rejected_frees += 1;
            return verdict;
        }
        self.live -= 1;
        self.stats.frees += 1;
        if self.live == 0 {
            self.next = self.start;
        }
        self.update_usage();
        Ok(())
    }

    fn stats(&self) -> AllocStats {
        let free = self.end - self.next;
        AllocStats {
            free_blocks: usize::from(free > 0),
            largest_free: free,
            total_free: free,
            ..self.stats
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::mem::testutil::Arena;

    #[test]
    fn bumps_aligns_and_resets_only_when_empty() {
        let mut arena = Arena::new(1024);
        let mut a = BumpAllocator::empty();
        let base = arena.start();
        unsafe { a.init(base, 1024) };
        let p1 = a.alloc(Layout::from_size_align(10, 1).unwrap());
        let p2 = a.alloc(Layout::from_size_align(8, 64).unwrap());
        assert_eq!(p1 as usize, base);
        assert_eq!(p2 as usize % 64, 0);
        unsafe { a.dealloc(p1, Layout::new::<u8>()).unwrap() };
        assert!(a.stats().bytes_in_use > 0, "space is not reused while p2 is live");
        unsafe { a.dealloc(p2, Layout::new::<u8>()).unwrap() };
        assert_eq!(a.stats().bytes_in_use, 0);
        assert_eq!(a.alloc(Layout::new::<u8>()) as usize, base);
    }

    #[test]
    fn exhaustion_and_rejected_frees() {
        let mut arena = Arena::new(128);
        let mut a = BumpAllocator::empty();
        unsafe { a.init(arena.start(), 128) };
        assert!(a.alloc(Layout::from_size_align(200, 8).unwrap()).is_null());
        assert_eq!(a.stats().failed, 1);
        let mut local = 0u8;
        let err = unsafe { a.dealloc(&mut local, Layout::new::<u8>()) };
        assert_eq!(err, Err(FreeError::OutOfRange));
        assert_eq!(a.stats().rejected_frees, 1);
    }
}

core/src/mem/freelist.rs.text:
//! Free-list allocator with block headers, splitting and coalescing.
//!
//! Memory layout (all addresses and sizes are multiples of 16):
//!
//! ```text
//!  allocated block:  [ Header{size, LIVE_MAGIC} ][ payload ........ ]
//!  free block:       [ FreeNode{size, next}     ][ unused ......... ]
//! ```
//!
//! Free blocks form a singly linked list sorted by address, which makes
//! coalescing with both neighbours a local operation on insert. The header
//! records the real block size, so `dealloc` does not trust the caller's
//! `Layout`, and the magic word lets us refuse double and foreign frees.

use core::alloc::Layout;
use core::ptr::null_mut;

use super::{align_up, AllocStats, FreeError, RegionAllocator};

/// Size of the per-block header and the granularity of every block.
pub const HEADER: usize = 16;
/// Smallest block worth tracking: header plus 16 bytes of payload.
pub const MIN_BLOCK: usize = 32;
/// Marks a live allocation. It is odd, so it can never equal the 16-aligned
/// (or null) `next` pointer that overwrites it once the block is freed.
const LIVE_MAGIC: usize = 0xA110_CA7E_D0C5_B10B;

#[repr(C)]
struct FreeNode {
    size: usize,
    next: *mut FreeNode,
}

#[repr(C)]
struct Header {
    size: usize,
    magic: usize,
}

/// Placement strategy when several free blocks could satisfy a request.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Fit {
    /// Lowest-addressed block that fits: fast, tends to fragment the front.
    First,
    /// Smallest block that fits: scans the whole list, keeps big blocks intact.
    Best,
}

pub struct FreeListAllocator {
    start: usize,
    end: usize,
    head: *mut FreeNode,
    fit: Fit,
    stats: AllocStats,
}

// SAFETY: the allocator exclusively owns its region and the raw pointers in
// the list only ever point into that region, so moving it to another
// context does not create shared mutable access.
unsafe impl Send for FreeListAllocator {}

/// Where a request would be placed inside one free block.
struct Placement {
    hdr: usize,
    front: usize,
    need: usize,
}

impl FreeListAllocator {
    pub const fn empty(fit: Fit) -> Self {
        Self { start: 0, end: 0, head: null_mut(), fit, stats: AllocStats::new() }
    }

    /// # Safety
    /// `[start, start + size)` must be valid, writable memory that nothing
    /// else uses for as long as this allocator manages it.
    pub unsafe fn init(&mut self, start: usize, size: usize) {
        let s = align_up(start, HEADER);
        let e = (start + size) & !(HEADER - 1);
        self.start = s;
        self.end = e;
        self.head = null_mut();
        self.stats = AllocStats { capacity: e.saturating_sub(s), ..AllocStats::new() };
        if e > s && e - s >= MIN_BLOCK {
            let node = s as *mut FreeNode;
            node.write(FreeNode { size: e - s, next: null_mut() });
            self.head = node;
        }
    }

    pub fn fit(&self) -> Fit {
        self.fit
    }

    /// Heap map: split the region into `out.len()` equal slices and write how
    /// full each one is, 0 (all free) to 255 (no free byte), by walking the
    /// free list. Reads only; allocates nothing, so it is safe to call while
    /// the heap lock is held. Block headers count as used.
    pub fn occupancy(&self, out: &mut [u8]) {
        let n = out.len();
        if n == 0 {
            return;
        }
        let span = self.end.saturating_sub(self.start);
        if span == 0 {
            out.fill(0);
            return;
        }
        // Free bytes per slice (at most 256 slices, a fixed stack array, so
        // nothing is allocated); each free block is split across the slices
        // it spans.
        let slice = span.div_ceil(n);
        let mut free = [0usize; 256];
        let buckets = n.min(free.len());
        let mut node = self.head;
        while !node.is_null() {
            // SAFETY: every node on the list was written by insert_free/init
            // inside [start, end) and is not part of a live block; the list is
            // only changed through &mut self, which this &self call excludes.
            let (addr, size, next) = unsafe { (node as usize, (*node).size, (*node).next) };
            let (mut a, b) = (addr - self.start, addr - self.start + size);
            while a < b {
                let i = (a / slice).min(buckets - 1);
                let edge = ((i + 1) * slice).min(b);
                free[i] += edge - a;
                a = edge;
            }
            node = next;
        }
        for (i, o) in out.iter_mut().enumerate().take(buckets) {
            let len = slice.min(span - (i * slice).min(span)).max(1);
            let used = len.saturating_sub(free[i].min(len));
            *o = ((used * 255 + len / 2) / len) as u8;
        }
        out[buckets..].fill(0);
    }

    /// Try to place `layout` in the free block `[block, block + size)`.
    fn place(block: usize, size: usize, layout: Layout) -> Option<Placement> {
        let align = layout.align().max(HEADER);
        let need = HEADER + align_up(layout.size().max(1), HEADER);
        let mut payload = align_up(block + HEADER, align);
        // A gap in front of the header must be 0 or big enough to stay a free block.
        while {
            let front = payload - HEADER - block;
            front != 0 && front < MIN_BLOCK
        } {
            payload += align;
        }
        let hdr = payload - HEADER;
        let end = hdr.checked_add(need)?;
        (end <= block + size).then_some(Placement { hdr, front: hdr - block, need })
    }

    /// Insert `[addr, addr + size)` into the address-ordered list and merge it
    /// with adjacent free neighbours.
    ///
    /// # Safety
    /// The range must lie inside the region and not be part of a live block.
    unsafe fn insert_free(&mut self, addr: usize, size: usize) -> Result<(), FreeError> {
        let mut prev: *mut FreeNode = null_mut();
        let mut cur = self.head;
        while !cur.is_null() && (cur as usize) < addr {
            prev = cur;
            cur = (*cur).next;
        }
        // Overlap with a neighbour means a double free or corrupted metadata.
        if !prev.is_null() && prev as usize + (*prev).size > addr {
            return Err(FreeError::Corrupt);
        }
        if !cur.is_null() && addr + size > cur as usize {
            return Err(FreeError::Corrupt);
        }
        let node = addr as *mut FreeNode;
        node.write(FreeNode { size, next: cur });
        if prev.is_null() {
            self.head = node;
        } else {
            (*prev).next = node;
        }
        if !cur.is_null() && addr + size == cur as usize {
            (*node).size += (*cur).size;
            (*node).next = (*cur).next;
        }
        if !prev.is_null() && prev as usize + (*prev).size == addr {
            (*prev).size += (*node).size;
            (*prev).next = (*node).next;
        }
        Ok(())
    }

    /// Validate `ptr` and put its block back on the free list.
    ///
    /// # Safety
    /// The header read at `ptr - HEADER` is only trusted after the range and
    /// alignment checks prove it lies inside our region; the magic check then
    /// rejects anything that is not a live block. The caller must not use
    /// `ptr` again if the free succeeds.
    unsafe fn free_block(&mut self, ptr: *mut u8) -> Result<usize, FreeError> {
        let p = ptr as usize;
        if p < self.start + HEADER || p >= self.end {
            return Err(FreeError::OutOfRange);
        }
        if p % HEADER != 0 {
            return Err(FreeError::Misaligned);
        }
        let hdr = (p - HEADER) as *mut Header;
        if (*hdr).magic != LIVE_MAGIC {
            return Err(FreeError::NotAllocated);
        }
        let size = (*hdr).size;
        if size < MIN_BLOCK || size % HEADER != 0 || hdr as usize + size > self.end {
            return Err(FreeError::Corrupt);
        }
        // Writing the FreeNode overwrites `magic`, so a second free is caught.
        self.insert_free(hdr as usize, size)?;
        Ok(size)
    }

    /// Walk the free list: (block count, largest block, total free bytes).
    fn scan(&self) -> (usize, usize, usize) {
        let (mut n, mut largest, mut total) = (0, 0, 0);
        let mut cur = self.head;
        while !cur.is_null() {
            // SAFETY: list nodes are written only by `init`/`insert_free`
            // inside the region this allocator owns.
            let (size, next) = unsafe { ((*cur).size, (*cur).next) };
            n += 1;
            largest = largest.max(size);
            total += size;
            cur = next;
        }
        (n, largest, total)
    }
}

impl RegionAllocator for FreeListAllocator {
    fn name(&self) -> &'static str {
        match self.fit {
            Fit::First => "first-fit",
            Fit::Best => "best-fit",
        }
    }

    fn alloc(&mut self, layout: Layout) -> *mut u8 {
        // SAFETY: every node reached from `head` was written by `init` or
        // `insert_free` inside our region; blocks we split are removed from
        // the list before their memory is reused.
        unsafe {
            let mut prev: *mut FreeNode = null_mut();
            let mut cur = self.head;
            let mut chosen: Option<(*mut FreeNode, *mut FreeNode, Placement)> = None;
            let mut best_size = usize::MAX;
            while !cur.is_null() {
                let size = (*cur).size;
                if let Some(p) = Self::place(cur as usize, size, layout) {
                    match self.fit {
                        Fit::First => {
                            chosen = Some((prev, cur, p));
                            break;
                        }
                        Fit::Best if size < best_size => {
                            best_size = size;
                            chosen = Some((prev, cur, p));
                        }
                        Fit::Best => {}
                    }
                }
                prev = cur;
                cur = (*cur).next;
            }
            let Some((prev, node, p)) = chosen else {
                self.stats.failed += 1;
                return null_mut();
            };

            let block = node as usize;
            let block_size = (*node).size;
            if prev.is_null() {
                self.head = (*node).next;
            } else {
                (*prev).next = (*node).next;
            }

            let mut used = p.need;
            let tail = block + block_size - (p.hdr + p.need);
            if tail >= MIN_BLOCK {
                let _ = self.insert_free(p.hdr + p.need, tail);
            } else {
                used += tail; // too small to track: hand it out with the block
            }
            if p.front > 0 {
                let _ = self.insert_free(block, p.front);
            }
            (p.hdr as *mut Header).write(Header { size: used, magic: LIVE_MAGIC });
            self.stats.record_alloc(used);
            (p.hdr + HEADER) as *mut u8
        }
    }

    // Safety: the Allocator::dealloc contract (no use of `ptr` afterwards).
    // free_block checks range, alignment and the header magic before
    // writing anything, so a bad pointer is refused rather than freed.
    unsafe fn dealloc(&mut self, ptr: *mut u8, _layout: Layout) -> Result<(), FreeError> {
        match self.free_block(ptr) {
            Ok(size) => {
                self.stats.frees += 1;
                self.stats.bytes_in_use -= size;
                Ok(())
            }
            Err(e) => {
                self.stats.rejected_frees += 1;
                Err(e)
            }
        }
    }

    fn stats(&self) -> AllocStats {
        let (free_blocks, largest_free, total_free) = self.scan();
        AllocStats { free_blocks, largest_free, total_free, ..self.stats }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::mem::testutil::Arena;
    use crate::rng::XorShift64;

    fn new(arena: &mut Arena, size: usize, fit: Fit) -> FreeListAllocator {
        let mut a = FreeListAllocator::empty(fit);
        unsafe { a.init(arena.start(), size) };
        a
    }

    fn l(size: usize, align: usize) -> Layout {
        Layout::from_size_align(size, align).unwrap()
    }

    #[test]
    fn alloc_free_coalesces_back_to_one_block() {
        let mut arena = Arena::new(4096);
        let mut a = new(&mut arena, 4096, Fit::First);
        let ptrs: Vec<_> = (0..8).map(|i| a.alloc(l(40 + i * 8, 8))).collect();
        assert!(ptrs.iter().all(|p| !p.is_null()));
        // free in an interleaved order to force merges on both sides
        for &i in &[1, 3, 5, 7, 0, 2, 6, 4] {
            unsafe { a.dealloc(ptrs[i], l(1, 1)).unwrap() };
        }
        let s = a.stats();
        assert_eq!((s.free_blocks, s.largest_free, s.bytes_in_use), (1, 4096, 0));
        assert_eq!(s.fragmentation_bp(), 0);
    }

    #[test]
    fn honours_large_alignment() {
        let mut arena = Arena::new(64 * 1024);
        let mut a = new(&mut arena, 64 * 1024, Fit::First);
        let small = a.alloc(l(24, 8));
        for align in [32, 64, 256, 4096] {
            let p = a.alloc(l(100, align));
            assert!(!p.is_null());
            assert_eq!(p as usize % align, 0, "align {align}");
        }
        assert!(!small.is_null());
    }

    #[test]
    fn rejects_double_foreign_and_misaligned_frees() {
        let mut arena = Arena::new(1024);
        let mut a = new(&mut arena, 1024, Fit::First);
        let p = a.alloc(l(64, 8));
        let q = a.alloc(l(64, 8));
        unsafe {
            assert_eq!(a.dealloc(p, l(64, 8)), Ok(()));
            assert_eq!(a.dealloc(p, l(64, 8)), Err(FreeError::NotAllocated));
            assert_eq!(a.dealloc(q.add(8), l(64, 8)), Err(FreeError::Misaligned));
            let mut local = 0u8;
            assert_eq!(a.dealloc(&mut local, l(1, 1)), Err(FreeError::OutOfRange));
            assert_eq!(a.dealloc(q, l(64, 8)), Ok(()));
        }
        assert_eq!(a.stats().rejected_frees, 3);
        assert_eq!(a.stats().free_blocks, 1);
    }

    #[test]
    fn exhaustion_returns_null_and_recovers() {
        let mut arena = Arena::new(1024);
        let mut a = new(&mut arena, 1024, Fit::First);
        let mut live = Vec::new();
        loop {
            let p = a.alloc(l(100, 8));
            if p.is_null() {
                break;
            }
            live.push(p);
        }
        assert!(a.stats().failed >= 1);
        assert!(a.alloc(l(2000, 8)).is_null());
        for p in live {
            unsafe { a.dealloc(p, l(100, 8)).unwrap() };
        }
        assert_eq!(a.stats().largest_free, 1024);
    }

    #[test]
    fn best_fit_picks_the_tightest_hole() {
        for (fit, expect_small_hole) in [(Fit::First, false), (Fit::Best, true)] {
            let mut arena = Arena::new(8192);
            let mut a = new(&mut arena, 8192, fit);
            // Layout: [big 512][sep][small 96][sep][rest]
            let big = a.alloc(l(496, 16));
            let _s1 = a.alloc(l(16, 16));
            let small = a.alloc(l(80, 16));
            let _s2 = a.alloc(l(16, 16));
            unsafe {
                a.dealloc(big, l(1, 1)).unwrap();
                a.dealloc(small, l(1, 1)).unwrap();
            }
            let p = a.alloc(l(64, 16));
            assert_eq!(p == small, expect_small_hole, "{fit:?}");
        }
    }

    /// Random alloc/free against a shadow model: blocks never overlap and
    /// their contents are never clobbered by allocator metadata.
    #[test]
    fn randomized_against_shadow_model() {
        for fit in [Fit::First, Fit::Best] {
            let mut arena = Arena::new(256 * 1024);
            let mut a = new(&mut arena, 256 * 1024, fit);
            let mut rng = XorShift64::new(7);
            let mut live: Vec<(*mut u8, usize, u8)> = Vec::new();
            for step in 0..20_000u32 {
                if live.is_empty() || (live.len() < 300 && rng.chance(55)) {
                    let size = rng.range(1, 3000) as usize;
                    let align = 1usize << rng.range(0, 7);
                    let p = a.alloc(l(size, align));
                    if p.is_null() {
                        continue;
                    }
                    assert_eq!(p as usize % align, 0);
                    let tag = step as u8;
                    unsafe { core::ptr::write_bytes(p, tag, size) };
                    live.push((p, size, tag));
                } else {
                    let i = rng.range(0, live.len() as u64) as usize;
                    let (p, size, tag) = live.swap_remove(i);
                    let ok = unsafe { core::slice::from_raw_parts(p, size) }.iter().all(|&b| b == tag);
                    assert!(ok, "payload corrupted");
                    unsafe { a.dealloc(p, l(size, 1)).unwrap() };
                }
            }
            for (p, size, _) in live.drain(..) {
                unsafe { a.dealloc(p, l(size, 1)).unwrap() };
            }
            let s = a.stats();
            assert_eq!((s.free_blocks, s.bytes_in_use, s.rejected_frees), (1, 0, 0));
        }
    }

    #[test]
    fn occupancy_maps_used_and_free_slices() {
        let mut buf = vec![0u8; 64 * 1024 + 16];
        let mut a = FreeListAllocator::empty(Fit::First);
        unsafe { a.init(buf.as_mut_ptr() as usize, buf.len()) };
        let mut map = [0u8; 8];
        a.occupancy(&mut map);
        assert!(map.iter().all(|&v| v == 0), "empty heap must map as free: {map:?}");
        // First-fit fills from the front: about one slice of 8 KiB.
        let p = a.alloc(Layout::from_size_align(8 * 1024 - 64, 16).unwrap());
        assert!(!p.is_null());
        a.occupancy(&mut map);
        assert!(map[0] > 240, "front slice should be (nearly) full: {map:?}");
        assert!(map[2..].iter().all(|&v| v == 0), "rest stays free: {map:?}");
        unsafe { a.dealloc(p, Layout::from_size_align(8 * 1024 - 64, 16).unwrap()).unwrap() };
        a.occupancy(&mut map);
        assert!(map.iter().all(|&v| v == 0), "freed heap maps as free again: {map:?}");
    }
}

